window.LCAT = {"tables":{"dim_date":{"a":"Calendar and registry","d":"Calendar spine covering every day with chain or Intents data.","g":["date_day"],"n":2307,"f":"2020-07-21","l":"2026-11-13","s":[],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["week_start","DATE","date","Monday of the week, UTC.",0,1],["week_start_sunday","DATE","date","Sunday on or before the day, UTC: the week as GitHub cuts it. Join fct_dev_activity_weekly.week_start to this column, not to week_start, which is a Monday and never matches.",0,1],["month_start","DATE","date","First day of the month.",0,1],["quarter_start","DATE","date","First day of the quarter.",0,1],["calendar_year","BIGINT","year","Calendar year.",0,0],["is_fee_switch_active","BOOLEAN","boolean","True from 2026-02-23, the first day of Intents buybacks per DefiLlama's adapter.",["defillama"],0]]},"dim_entity":{"a":"Calendar and registry","d":"The reviewed wallet registry joined to what the chain reports today. Every label carries an evidence level and a source URL.","g":["account_id"],"n":64,"f":null,"l":null,"s":["rpc","fastnear","registry"],"c":[["account_id","VARCHAR","account id","NEAR account.",0,1],["entity","VARCHAR","text","Organization that runs the account, as far as the evidence shows. Unlabelled means not established.",0,0],["category","VARCHAR","text","Functional group.",0,0],["role","VARCHAR","text","What the account does.",0,0],["tier","INTEGER","integer","Depth priority: 1 Intents and revenue, 2 security and staking, 3 DeFi and stablecoins, 4 usage heavyweights.",0,0],["tracks_holdings","BOOLEAN","boolean","Holdings are snapshotted nightly.",0,0],["tracks_contract_stats","BOOLEAN","boolean","Daily contract stats are fetched.",0,0],["crawls_transfers","BOOLEAN","boolean","All transfers are crawled.",0,0],["evidence_level","VARCHAR","text","Strength of the label: documented, chain, token_list, third_party_code, observed or name_only.",0,0],["source_url","VARCHAR","url","Where the evidence can be checked.",0,0],["note","VARCHAR","text","Caveat on this label.",0,0],["account_exists","BOOLEAN","boolean","Whether the chain knows this account. False is expected for implicit accounts that only hold balances inside intents.near.",0,0],["has_contract","BOOLEAN","boolean","Whether code is deployed on the account.",0,0],["balance_near","DOUBLE","NEAR","Native balance.",0,0],["storage_bytes","BIGINT","bytes","Storage used.",0,0],["cumulative_txns","BIGINT","count","Transactions touching the account since genesis, per FastNear.",["fastnear"],0],["checked_on","DATE","date","Date of the on-chain check.",0,1]]},"dim_token":{"a":"Calendar and registry","d":"Registry tokens with their decimals and, where 1Click lists them, a CoinGecko id. Prices are in fct_token_prices.","g":["token_id"],"n":12,"f":null,"l":null,"s":["explorer","registry"],"c":[["token_id","VARCHAR","token id","Token contract, or Intents asset id.",0,1],["symbol","VARCHAR","text","Token symbol.",0,0],["token_class","VARCHAR","text","Kind of token.",0,0],["tracks_holders","BOOLEAN","boolean","Top holders are snapshotted nightly.",0,0],["evidence_level","VARCHAR","text","Strength of the label: documented, chain, token_list, third_party_code, observed or name_only.",0,0],["source_url","VARCHAR","url","Where the evidence can be checked.",0,0],["note","VARCHAR","text","Caveat on this row.",0,0],["decimals","INTEGER","integer","Token decimals from registry/tokens.csv, each read from the contract's ft_metadata; 1Click's figure is the fallback and a data test holds the two to each other.",0,0],["coingecko_id","VARCHAR","id","CoinGecko identifier.",0,0]]},"dim_event":{"a":"Calendar and registry","d":"Dated protocol, governance, product and market events, each with a source URL. Use for chart annotations and event studies.","g":["event_date","title"],"n":34,"f":"2024-12-10","l":"2026-12-30","s":["registry"],"c":[["event_date","DATE","date","Date of the event.",0,1],["event_type","VARCHAR","text","Kind of event.",0,0],["title","VARCHAR","text","Short title.",0,1],["detail","VARCHAR","text","One line of detail.",0,0],["source_url","VARCHAR","url","Where the evidence can be checked.",0,0],["status","VARCHAR","text","happened, voting while the vote is open, or scheduled for an event that has been announced with a date still ahead.",0,0]]},"dim_block_day":{"a":"Calendar and registry","d":"One block per UTC day from the archival node: monthly from 2020-08, daily from 2025-01. Each block falls within 120 seconds after 00:00 UTC.","g":["date_day"],"n":736,"f":"2020-08-01","l":"2026-11-14","s":["rpc"],"c":[["date_day","DATE","date","UTC day this block represents.",0,1],["block_height","BIGINT","blocks","Block height.",0,0],["block_hash","VARCHAR","hash","Block hash.",0,0],["block_timestamp_ns","HUGEINT","nanoseconds since epoch","Block timestamp.",0,0],["total_supply_near","DOUBLE","NEAR","Total supply in this block.",0,0],["gas_price_yocto","HUGEINT","yoctoNEAR per gas","Gas price in the block.",0,0],["epoch_id","VARCHAR","hash","Epoch identifier.",0,0],["protocol_version","INTEGER","integer","latest_protocol_version in the block header: the version the block's producer supports, which can lead the version in force by days. 87 was in the header by the first block of 2026-11-04 and took effect at 11:46:29 UTC that day, with block 223012337. Date a change from registry/protocol_upgrades.csv or fct_protocol_config.",0,0]]},"dim_protocol":{"a":"Calendar and registry","d":"Protocols DefiLlama lists on NEAR, as of the newest reading that listed each one. A protocol is one DefiLlama id, so a rename, which changes the slug and keeps the id, gives one row under the newest slug. A protocol missing from the newest reading keeps its row with an older read_on, because a missed night and a delisting look the same. Exchange wallets are marked with is_cex.","g":["protocol_id"],"n":47,"f":null,"l":null,"s":["defillama"],"c":[["protocol_id","VARCHAR","id","DefiLlama's id for the protocol. It stays the same when the protocol is renamed.",0,1],["protocol_slug","VARCHAR","id","DefiLlama's URL name for the protocol, as of the newest reading that listed it. It can change.",0,0],["protocol_name","VARCHAR","text","Protocol name.",0,0],["category","VARCHAR","text","DefiLlama category.",0,0],["url","VARCHAR","url","Protocol website.",0,0],["parent_protocol","VARCHAR","id","DefiLlama parent protocol.",0,0],["near_tvl_usd","DOUBLE","USD","TVL on NEAR.",0,0],["total_tvl_usd","DOUBLE","USD","TVL across all chains.",0,0],["is_cex","BOOLEAN","boolean","True for exchange wallets, which DefiLlama leaves out of chain TVL.",0,0],["read_on","DATE","date","Date of the newest reading that listed the protocol. Older than the table's newest date means it was missing from later readings, and its figures are as of this date.",0,1]]},"dim_source":{"a":"Calendar and registry","d":"Every data source with its access, limits and terms.","g":["source"],"n":24,"f":null,"l":null,"s":["registry"],"c":[["source","VARCHAR","id","Source name, as used in bronze paths.",0,1],["provides","VARCHAR","text","What the source is used for.",0,0],["access","VARCHAR","text","Whether a key is needed.",0,0],["limit_observed","VARCHAR","text","Rate limit as published or observed.",0,0],["terms_url","VARCHAR","url","Where the terms are.",0,0],["terms_summary","VARCHAR","text","What the terms say, as far as they were read. Not legal advice.",0,0],["publication_note","VARCHAR","text","How this source's data is used here: with credit, as decided on 2026-11-13 where its terms left that open, or why no decision was needed. DATA_NOTICE.md says how a source can ask for removal.",0,0]]},"fct_chain_daily":{"a":"Chain usage, supply and parameters","d":"Chain usage per UTC day, one column per measure. Most counts come from NearBlocks /v3, which returns the last 365 days of each read, and from /v1/charts for older days: the two agree day for day wherever both exist, dq_reconciliation compares them, and /v1 is switched off on 2026-11-22. Where /v1 and /v3 count different things both are kept, under names that say what each counts: active_signers and active_accounts_with_relayed, new_contracts_v1 and new_contracts_v3. Levels of txns, receipts, active accounts, contracts, new accounts and meta columns cannot be compared across 2026-04-02: see docs/USAGE_BREAK_2026-04-02.md.","g":["date_day"],"n":2307,"f":"2020-07-21","l":"2026-11-13","s":["nearblocks"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["txns","BIGINT","count","Transactions: /v3/txn-stats, else /v1/charts for older days. The two agree on every day both hold.",0,0],["meta_txns","BIGINT","count","Meta-transactions, where a relayer pays gas for the user.",0,0],["meta_txn_share","DOUBLE","fraction","meta_txns divided by txns.",0,0],["receipts","BIGINT","count","Receipts.",0,0],["blocks","BIGINT","count","Blocks: /v3/block-stats, else /v1/charts.",0,0],["chunks","BIGINT","count","Chunks across all shards. Last 365 days of reads only.",0,0],["shards","INTEGER","count","Shards that day. Last 365 days of reads only.",0,0],["gas_price_yocto","DOUBLE","yoctoNEAR per gas","Gas price per NearBlocks /v3/block-stats. Last 365 days of reads only. It has sat at the protocol's minimum all year; dim_block_day holds the price in one block a day.",0,0],["active_signers","BIGINT","count","Active accounts per /v1/charts. NearBlocks does not document it, but it matches Nansen's published distinct signers, so it leaves out users whose transactions a relayer signs. Ends on 2026-11-22, when /v1 is switched off.",0,0],["active_accounts_with_relayed","BIGINT","count","Active accounts per /v3/address-stats. NearBlocks does not document it, but it stays within 2% of active_signers plus meta_accounts, so it also counts users whose transactions a relayer signs. About 2x active_signers in the latest 30 days, and 9x to 18x in monthly averages before 2026-04-02.",0,0],["distinct_signers","BIGINT","count","Accounts that signed a transaction that day, by one rule: active_signers minus deleted_accounts on a day /v1/charts holds, and active_accounts_with_relayed minus meta_accounts on a day it does not. An account signs its own deletion, so active_signers rises by one for every account deleted that day (3.4M accounts in February 2026 and 562K in October 2026), and this column leaves them out. On ordinary days from April to November 2026 the two forms differ by -3.2% to +1.7%. Deletion days cannot be taken out of the second form. Not people: about 60% of active accounts call one game.",0,0],["distinct_signers_basis","VARCHAR","label","Which form distinct_signers takes on the day: v1_signers_less_deletions while /v1/charts holds the day (it is switched off on 2026-11-22), v3_active_less_relayed after.",0,0],["active_contracts","BIGINT","count","Active contracts: /v3/address-stats, else /v1/charts. The two agree except on 2026-04-15 and by one contract on three days. Not a count of applications in use: it follows the scripted streams, averaging 721 a day in May 2024, 2.19 million in March 2026 and 95,000 in May 2026, after they stopped.",0,0],["new_accounts","BIGINT","count","Accounts created, per /v1/charts. Ends on 2026-11-22.",0,0],["deleted_accounts","BIGINT","count","Accounts deleted, per /v1/charts. Ends on 2026-11-22.",0,0],["new_contracts_v1","BIGINT","count","Contracts deployed, per /v1/charts. NearBlocks documents neither its own count nor new_contracts_v3, and the two differ by 25% at the median, so they are kept apart. Ends on 2026-11-22.",0,0],["new_contracts_v3","BIGINT","count","New contracts per /v3/address-stats; see new_contracts_v1.",0,0],["unique_contracts","BIGINT","count","Distinct contract code hashes deployed, per /v1/charts. Ends on 2026-11-22.",0,0],["meta_accounts","BIGINT","count","Accounts sending meta-transactions.",0,0],["meta_relayers","BIGINT","count","Relayers submitting meta-transactions.",0,0],["gas_used","DOUBLE","gas units","Gas used: /v3/block-stats, else /v1/charts.",0,0],["gas_fee_near","DOUBLE","NEAR","Gas fees: /v3/block-stats, else /v1/charts. The two agree to the unit on every day both hold.",0,0],["txn_fee_near","DOUBLE","NEAR","Transaction fees: /v3/txn-stats, else /v1/charts. The two agree except on 2026-04-15. Not the same as gas_fee_near, which runs about 5% higher at the median.",0,0],["txn_volume_near","DOUBLE","NEAR","NEAR moved by transactions: /v3/txn-stats, else /v1/charts.",0,0]]},"fct_supply_daily":{"a":"Chain usage, supply and parameters","d":"Supply and implied issuance per UTC day. Epochs end at uneven times, so one day's minted_near is lumpy; use averages of 30 days or more. Circulating supply is in fct_circulating_supply_daily, and gas fees are in fct_chain_daily.","g":["date_day"],"n":2307,"f":"2020-07-21","l":"2026-11-13","s":["rpc","fastnear","nearblocks"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["total_supply_near","DOUBLE","NEAR","Total supply at day end per NearBlocks: /v3/block-stats, else /v1/charts for older days. It equals the chain's own supply in the first block of the next day on every day the archival node was read, which a data test holds.",["nearblocks"],0],["supply_change_near","DOUBLE","NEAR","Change in total supply from the previous day.",0,0],["contract_gas_reward_rate","DOUBLE","fraction","Share of function-call gas paid to the called contract on that day (the developer gas rebate): the newest protocol config read on or before the day, and the first read's 0.3 before 2026-10-28. A change that registry/protocol_upgrades.csv dates to the block holds from the next day, and its own day takes both rates weighted by the time each was in force, as if gas were spread evenly over the day: 0.147 on 2026-11-04, when protocol version 87 set the share to 0 at 11:46:29 UTC.",["rpc"],0],["burn_near","DOUBLE","NEAR","Gas fees (fct_chain_daily.gas_fee_near) times one minus contract_gas_reward_rate. The rebate came only out of gas burnt executing function calls, so before protocol version 87 the real burn was more than 70% of gas and this is a lower bound; the upper bound is the whole fee, fct_chain_daily.gas_fee_near. The burn can be read straight off the chain only before issuance began on 2020-10-20, when every fall in supply was gas burned: over those 79 days supply fell by 84.8% of gas fees, 124.4 NEAR against this column's 102.7, and the lower bound held on every one of them, which a data test keeps. That share belongs to 2020's mix of transactions and is not applied to later years. From 11:46:29 UTC on 2026-11-04 all gas burns; that day itself is the time-weighted mix.",0,0],["treasury_reward_near","DOUBLE","NEAR","EpochRewards received by treasury.near that day, from wallet transfers. Part of minted_near, not on top of it.",["fastnear"],0],["minted_near","DOUBLE","NEAR","supply_change_near plus burn_near: issuance implied by the chain. It inherits burn_near's lower bound, so before 2026-11-04 the real figure is higher by up to 30% of that day's gas fee, which is small against issuance: 3.36M NEAR of modelled burn against 314.5M minted through 2026-11-08.",0,0],["minted_annualized_rate","DOUBLE","fraction per year","minted_near times 365, divided by total supply. Noisy for a single day.",0,0]]},"fct_circulating_supply_daily":{"a":"Chain usage, supply and parameters","d":"NEAR's circulating supply per UTC day, built from the chain, from the day transfers were enabled. NEAR defines it as every token not subject to a lockup at that moment. This uses NEAR Explorer's formula: total supply, minus what every lockup contract still locks, minus the balances of lockup.near and contributors.near. Tested against NearBlocks' own lockup job while that ran, NEAR's published schedule, and the contracts' own answers. It does not take out the NEAR Foundation's liquid holding or the protocol treasury, and it counts staked tokens as circulating. See docs/CIRCULATING_SUPPLY.md.","g":["date_day"],"n":2223,"f":"2020-10-13","l":"2026-11-13","s":["rpc","fastnear","nearblocks"],"c":[["date_day","DATE","date","UTC calendar day, read at its close. Starts on 2020-10-13.",0,1],["lockup_locked_near","DOUBLE","NEAR","Sum over all lockup contracts of the amount their schedule still locks at the day's close. A lockup whose owner never turned transfers on counts as released on schedule, as in NEAR Explorer; transfers_never_enabled_near holds those.",["rpc"],0],["foundation_locked_near","DOUBLE","NEAR","Balances of lockup.near, which funds new lockups, and contributors.near, which held 418M NEAR at genesis and has since paid nearly all of it out. NEAR Explorer subtracted these two and no other account.",0,0],["circulating_supply_near","DOUBLE","NEAR","Total supply from fct_supply_daily, minus lockup_locked_near, minus foundation_locked_near.",0,0],["circulating_share_of_total","DOUBLE","fraction","circulating_supply_near divided by total supply.",0,0],["lockups_existing","BIGINT","count","Lockup contracts that existed at the day's close. Contracts deleted later are counted until their last transfer.",["rpc"],0],["lockups_still_locking","BIGINT","count","Lockup contracts with anything still locked at the day's close.",["rpc"],0],["transfers_never_enabled_near","DOUBLE","NEAR","Held by lockups that exist today and whose owner has still not turned transfers on, so none of it has ever left its contract. It counts as circulating in circulating_supply_near, as in NEAR Explorer; a stricter reading subtracts it. Understated in the past, because a lockup that turned transfers on later is not in it for any day.",0,0]]},"fct_protocol_config":{"a":"Chain usage, supply and parameters","d":"Protocol parameters as read on each snapshot date. A change between rows is a protocol change.","g":["snapshot_date"],"n":15,"f":"2026-10-28","l":"2026-11-14","s":["rpc"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["protocol_version","INTEGER","integer","Protocol version.",0,0],["max_inflation_rate","DOUBLE","fraction per year","Maximum annual inflation parameter.",0,0],["protocol_reward_rate","DOUBLE","fraction","Share of issuance sent to the protocol treasury.",0,0],["contract_gas_reward_rate","DOUBLE","fraction","Share of function-call gas paid to the called contract.",0,0],["gas_burn_rate","DOUBLE","fraction","One minus contract_gas_reward_rate.",0,0],["epoch_length_blocks","BIGINT","blocks","Epoch length.",0,0],["block_producer_seats","INTEGER","count","Block producer seats.",0,0],["blocks_per_year_setting","BIGINT","blocks","Blocks per year used in the reward formula.",0,0],["shard_count","UBIGINT","count","Number of shards.",0,0],["storage_yocto_per_byte","HUGEINT","yoctoNEAR per byte","Storage staking cost.",0,0],["min_gas_price_yocto","HUGEINT","yoctoNEAR per gas","Minimum gas price parameter.",0,0],["protocol_treasury_account","VARCHAR","account id","Account that receives the protocol reward share.",0,0]]},"fct_contract_daily":{"a":"Chain usage, supply and parameters","d":"Daily transactions and unique callers per registry contract.","g":["date_day","account_id"],"n":18746,"f":"2023-12-01","l":"2026-11-13","s":["nearblocks"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["account_id","VARCHAR","account id","NEAR account.",0,1],["entity","VARCHAR","text","Organization that runs the account, as far as the evidence shows. Unlabelled means not established.",0,0],["category","VARCHAR","text","Functional group.",0,0],["txns","BIGINT","count","Transactions involving the contract that day, per NearBlocks' account statistics. For v1.signer it equals fct_chain_signatures_daily.txns, which dq_reconciliation checks.",0,0],["unique_callers","BIGINT","count","Distinct accounts calling the contract.",0,0],["unique_receivers","BIGINT","count","Distinct accounts the contract sent to.",0,0]]},"fct_receiver_sample_daily":{"a":"Chain usage, supply and parameters","d":"Activity per receiver, estimated from evenly spaced sample blocks. These are estimates, and a day's sample density is in blocks_sampled. Measured against the chain's own count (fct_chain_daily.txns) at the 2026-11-10 pin: with 24 blocks a day, from 2025-11-10 through 2026-10-29, a day's estimated transactions summed over receivers were 2% low in total and off by 13% at the median, 42% at the 90th percentile, and between 0.46 and 2.44 times the real count, with December 2025 to March 2026 the noisiest months; with 96 blocks, from 2026-10-30, 2% low in total and off by 6% at the median and 9% at the 90th percentile. So read a 24-block day as rough, and prefer shares over a week or more. A data test holds the estimates to the chain's count.","g":["date_day","account_id"],"n":205300,"f":"2025-11-10","l":"2026-11-13","s":["neardata"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["account_id","VARCHAR","account id","NEAR account.",0,1],["entity","VARCHAR","text","Organization that runs the account, as far as the evidence shows. Unlabelled means not established.",0,0],["category","VARCHAR","text","Functional group.",0,0],["sampled_txns","BIGINT","count","Transactions to this receiver in the sample.",0,0],["sampled_receipts","BIGINT","count","Receipts to this receiver in the sample.",0,0],["sampled_distinct_signers","BIGINT","count","Distinct transaction signers in the sample.",0,0],["txn_share","DOUBLE","fraction","Share of sampled transactions.",0,0],["receipt_share","DOUBLE","fraction","Share of sampled receipts.",0,0],["estimated_daily_receipts","DOUBLE","count","sampled_receipts scaled up by blocks_in_day over blocks_sampled.",0,0],["estimated_daily_txns","DOUBLE","count","sampled_txns scaled up by blocks_in_day over blocks_sampled.",0,0],["sampled_tokens_burnt_near","DOUBLE","NEAR","Tokens burnt in sampled receipts.",0,0],["blocks_sampled","INTEGER","count","Blocks sampled that day.",0,0],["blocks_in_day","BIGINT","blocks","Block height span of the day.",0,0]]},"fct_bigquery_chain_daily":{"a":"NEAR's public BigQuery dataset","d":"The chain per UTC day as counted in NEAR's public BigQuery dataset (bigquery-public-data.crypto_near_mainnet_us), the source the hackathon's sample prompt names. It stands beside fct_chain_daily, which takes the same measures from NearBlocks, and dq_reconciliation holds the two against each other. Blocks and total supply cover every day since genesis; transactions, signers and receivers start where the read of the transactions table starts, because that read is billed by size; the three *_table_rows columns are BigQuery's own count of rows in each table's daily partition, which costs nothing to read and covers every day. The SQL is in ingest/sql/bigquery/, and dq_bigquery_reads lists every read.","g":["date_day"],"n":2305,"f":"2020-07-21","l":"2026-11-11","s":["bigquery"],"c":[["date_day","DATE","date","UTC calendar day of the block.",0,1],["blocks","BIGINT","count","Blocks produced that day.",0,0],["first_block_height","BIGINT","blocks","Height of the day's first block.",0,0],["last_block_height","BIGINT","blocks","Height of the day's last block.",0,0],["last_block_at","TIMESTAMP","UTC timestamp","Time of the day's last block in the dataset when it was read.",0,1],["is_day_complete","BOOLEAN","boolean","True when the day's last block is within the last minute before midnight, so the whole day was loaded when it was read. A day that is not complete undercounts everything.",0,0],["block_producers","BIGINT","count","Distinct accounts that produced a block that day.",0,0],["total_supply_near","DOUBLE","NEAR","Total supply in the day's last block.",0,0],["txns","BIGINT","count","Transactions, counted from the transactions table. Empty before the window that table was read over.",0,0],["signers","BIGINT","count","Distinct accounts that signed a transaction. A relayer that signs for many users counts once, and those users do not count. An account also signs its own deletion.",0,0],["receivers","BIGINT","count","Distinct accounts a transaction was addressed to. A relayed transaction is addressed to the user's own account, so this rises with relayed activity.",0,0],["transactions_table_rows","BIGINT","count","Rows in the transactions table's partition for the day, from BigQuery's partition records. Equal to txns where both exist unless the table holds a transaction twice.",0,0],["receipt_details_table_rows","BIGINT","count","Rows in the receipt_details table's partition for the day: action receipts and data receipts together.",0,0],["receipt_actions_table_rows","BIGINT","count","Rows in the receipt_actions table's partition for the day: one per action inside an action receipt.",0,0]]},"fct_bigquery_receiver_daily":{"a":"NEAR's public BigQuery dataset","d":"Who the day's transactions were sent to, counted over every transaction in NEAR's public BigQuery dataset: each account among the day's 25 largest receivers by transactions or by distinct signers. fct_receiver_sample_daily estimates the same split from about one block in a thousand; this is the full count. A receiver is the account a transaction is addressed to, and a relayed transaction is addressed to the user's own account, so an application reached through a relayer does not appear here as one contract: fct_bigquery_contract_daily counts by the contract called. Accounts outside a day's top 25 never leave BigQuery.","g":["date_day","receiver_account_id"],"n":28313,"f":"2025-01-01","l":"2026-11-11","s":["bigquery","registry"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["receiver_account_id","VARCHAR","account id","Account the transactions were addressed to.",0,1],["entity","VARCHAR","text","Organization that runs the account, from the registry. Empty means not established.",["registry"],0],["category","VARCHAR","text","Functional group, from the registry.",["registry"],0],["txns","BIGINT","count","Transactions addressed to this account that day.",0,0],["signers","BIGINT","count","Distinct accounts that signed a transaction addressed to this account that day.",0,0],["txn_share","DOUBLE","fraction","txns divided by the day's transactions.",0,0],["signer_share","DOUBLE","fraction","signers divided by the day's distinct signers. A signer that used several accounts counts in each, so shares can add up to more than 1.",0,0],["rank_by_txns","INTEGER","rank","The account's rank that day by transactions, 1 the largest.",0,0],["rank_by_signers","INTEGER","rank","The account's rank that day by distinct signers, 1 the largest.",0,0]]},"fct_bigquery_contract_daily":{"a":"NEAR's public BigQuery dataset","d":"Which contracts the day's function calls went to, counted over every action receipt in NEAR's public BigQuery dataset: each contract among the day's 25 largest by calls, by distinct signers or by distinct callers. This is the count of accounts by application that NearBlocks and the block sample cannot give. signers are the accounts that signed the transaction a call came from, which for a relayed call is the relayer; callers are the accounts that sent the receipt, which for a relayed call is the user. Contracts outside a day's top 25 never leave BigQuery.","g":["date_day","contract_id"],"n":9546,"f":"2026-04-03","l":"2026-11-11","s":["bigquery","registry"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["contract_id","VARCHAR","account id","Account whose contract was called.",0,1],["entity","VARCHAR","text","Organization that runs the contract, from the registry. Empty means not established.",["registry"],0],["category","VARCHAR","text","Functional group, from the registry.",["registry"],0],["function_calls","BIGINT","count","Function-call actions sent to this contract that day, counting calls made by other contracts.",0,0],["signers","BIGINT","count","Distinct accounts that signed a transaction leading to a call of this contract. For relayed calls that is the relayer, so an application that pays for its users shows few signers.",0,0],["callers","BIGINT","count","Distinct accounts that sent a receipt calling this contract: users who called it directly, users a relayer signed for, and other contracts.",0,0],["call_share","DOUBLE","fraction","function_calls divided by the day's function calls.",0,0],["signer_share","DOUBLE","fraction","signers divided by the day's distinct signers of any function call. A signer that reached several contracts counts in each, so shares can add up to more than 1.",0,0],["caller_share","DOUBLE","fraction","callers divided by the day's distinct callers of any function call. An account that called several contracts counts in each, so shares can add up to more than 1.",0,0],["rank_by_calls","INTEGER","rank","The contract's rank that day by function calls, 1 the largest.",0,0],["rank_by_signers","INTEGER","rank","The contract's rank that day by distinct signers, 1 the largest.",0,0],["rank_by_callers","INTEGER","rank","The contract's rank that day by distinct callers, 1 the largest.",0,0]]},"fct_bigquery_action_daily":{"a":"NEAR's public BigQuery dataset","d":"What the chain did each UTC day by kind of action, counted over every action receipt in NEAR's public BigQuery dataset: FUNCTION_CALL, TRANSFER, CREATE_ACCOUNT, DELETE_ACCOUNT, ADD_KEY, DELETE_KEY, DEPLOY_CONTRACT, STAKE, DELEGATE_ACTION (a relayed request), and the newer kinds for global contracts and state initialisation as the dataset names them. DELEGATE_ACTION's actions and receivers are NearBlocks' meta-transactions and the accounts a relayer signed for, almost to the unit. Accounts deleted and contracts deployed are counts NearBlocks stops serving when /v1 is switched off on 2026-11-22. An action is one step inside a receipt, and a transaction can lead to many receipts, so these are not transaction counts.","g":["date_day","action_kind"],"n":2490,"f":"2026-04-03","l":"2026-11-11","s":["bigquery"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["action_kind","VARCHAR","text","Kind of action, as the dataset names it.",0,1],["actions","BIGINT","count","Actions of this kind that day.",0,0],["signers","BIGINT","count","Distinct accounts that signed the transaction an action of this kind came from. For a relayed action that is the relayer.",0,0],["predecessors","BIGINT","count","Distinct accounts that sent a receipt holding an action of this kind. For a relayed action that is the user. Includes contracts that act on other contracts, and the account named system, which sends refunds.",0,0],["receivers","BIGINT","count","Distinct accounts a receipt with an action of this kind went to: the contracts called for FUNCTION_CALL, the accounts created for CREATE_ACCOUNT, the accounts that received code for DEPLOY_CONTRACT, and so on.",0,0],["from_system","BIGINT","count","Actions in receipts sent by the account named system: refunds of unused gas and deposits, which arrive as transfers.",0,0],["actions_not_from_system","BIGINT","count","actions less from_system. For TRANSFER this is transfers that are not refunds.",0,0]]},"fct_bigquery_circulating_supply_daily":{"a":"NEAR's public BigQuery dataset","d":"NEAR's own daily circulating supply, as its lakehouse computes it and publishes it in the circulating_supply table of its public BigQuery dataset. It stands beside fct_circulating_supply_daily, which this warehouse builds from every lockup contract read on chain: two computations of the same figure by different hands, and dq_reconciliation holds them against each other. The site and the thesis read the warehouse's own series; this table is the outside check on it.","g":["date_day"],"n":1409,"f":"2023-01-01","l":"2026-11-11","s":["bigquery"],"c":[["date_day","DATE","date","UTC calendar day the figure is for.",0,1],["circulating_supply_near","DOUBLE","NEAR","Circulating supply as NEAR's lakehouse computes it: total supply less what lockup contracts still hold locked. Empty on a day the table reports zero.",0,0],["total_supply_near","DOUBLE","NEAR","Total supply at the block the figure was computed at.",0,0],["circulating_share_of_total","DOUBLE","fraction","circulating_supply_near divided by total_supply_near.",0,0],["not_circulating_near","DOUBLE","NEAR","total_supply_near less circulating_supply_near: what NEAR's computation counts as locked.",0,0],["is_zero_in_source","BOOLEAN","boolean","True on a day NEAR's table reports a circulating supply of zero. That is a fault in the table, so the day carries no circulating figure here.",0,0],["computed_at_block_height","BIGINT","blocks","Block the figure was computed at.",0,0],["computed_at","TIMESTAMP","UTC timestamp","Time of that block.",0,1]]},"fct_bigquery_signer_cohort_monthly":{"a":"NEAR's public BigQuery dataset","d":"Do accounts come back? Every account that ever signed a transaction is placed in the month it first signed one, its cohort, and counted again in each later month in which it signed at least one. Counted in NEAR's public BigQuery dataset over every transaction since genesis; no other source in this warehouse can do it, because it needs each signer's whole history. The row where active_month equals cohort_month is the cohort's size. An account also signs its own deletion, and a batch that creates accounts to use once fills a cohort with accounts that were never going to return, so read a cohort beside what happened that month.","g":["cohort_month","active_month"],"n":3003,"f":null,"l":null,"s":["bigquery"],"c":[["cohort_month","DATE","date","First day of the month in which these accounts first signed a transaction.",0,1],["active_month","DATE","date","First day of a month in which they signed at least one transaction.",0,1],["months_since_first","INTEGER","months","Whole months from cohort_month to active_month; 0 is the cohort's own month.",0,0],["signers","BIGINT","count","Accounts of the cohort that signed at least one transaction in active_month.",0,0],["cohort_signers","BIGINT","count","Size of the cohort: accounts that first signed in cohort_month.",0,0],["retained_share","DOUBLE","fraction","signers divided by cohort_signers.",0,0],["is_active_month_complete","BOOLEAN","boolean","False for the month the read ended in, which holds only its first days.",0,0],["read_through","DATE","date","Last day of transactions the read covered.",0,1]]},"fct_intents_daily":{"a":"NEAR Intents and revenue","d":"NEAR Intents per UTC day, one column per measure. All-route volume and gross fees are revenue.near.org's, which counts confidential routes too; on the few days the page lacks, DefiLlama fills in, and volume_basis and fees_basis say which. Public volume, swaps, accounts, tokens and chains are NearBlocks', which sees public Intents only, so volume_usd minus public_volume_usd is confidential volume. From 2026-11-03 almost all volume settles confidentially, so the public columns describe a small part of Intents. Captured revenue is DefiLlama's. DefiLlama's own volume and fees are not columns here: they count public routes only from 2026-04-01 (volume to 08-31, fees to 09-13), so dq_reconciliation compares them with the page and NearBlocks instead. The fee and revenue columns of the newest days can still change; see is_fee_revenue_provisional.","g":["date_day"],"n":704,"f":"2024-12-10","l":"2026-11-13","s":["nearblocks","defillama","revenue"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["volume_usd","DOUBLE","USD","All-route Intents volume, confidential routes included, per revenue.near.org. On the 29 days the page lacks, DefiLlama's figure: 22 days of December 2024, and 7 days between 2025-03-08 and 05-14 worth $12.85M that the page does not count at all.",["revenue"],0],["volume_basis","VARCHAR","text","Where volume_usd comes from: revenue_page or defillama.",["defillama","revenue"],0],["public_volume_usd","DOUBLE","USD","Public Intents volume per NearBlocks. Starts on 2025-10-29, the oldest day its 365-day window held at the first read. From 2026-11-03 almost all Intents volume settles confidentially, so this fell from about 60% of volume_usd in late October to between 0.4% and 18%; NEAR's own dashboard on Dune shows the same fall. The other public counts fell with it. It comes from another source than volume_usd, NearBlocks' reading of the chain against NEAR's own tally, so while nearly everything was public the two differed by noise: through 2026-04-20 it read above volume_usd on 88 days, by more than 2% on 4 of them and by 7.7% at most (2026-04-18). So volume_usd minus public_volume_usd is not a clean confidential series on such days; floor it at zero. A data test holds it within 10% above volume_usd.",["nearblocks"],0],["public_volume_cumulative_usd","DOUBLE","USD","All-time public Intents volume per NearBlocks, including the history before its 365-day window.",["nearblocks"],0],["public_swaps","BIGINT","count","Public Intents swaps per NearBlocks.",["nearblocks"],0],["public_accounts","BIGINT","count","Distinct accounts swapping through public Intents, per NearBlocks.",["nearblocks"],0],["public_tokens","BIGINT","count","Distinct tokens swapped through public Intents, per NearBlocks.",["nearblocks"],0],["public_chains","BIGINT","count","Distinct blockchains active in public Intents, per NearBlocks.",["nearblocks"],0],["fees_usd","DOUBLE","USD","All-route gross fees per revenue.near.org. On the 5 days of May 2025 the page lacks, DefiLlama's figure, $8 together.",["revenue"],0],["fees_basis","VARCHAR","text","Where fees_usd comes from: revenue_page or defillama.",["defillama","revenue"],0],["revenue_usd","DOUBLE","USD","Captured revenue per DefiLlama: NEAR and wNEAR swept into the revenue wallets, at the day's closing price. Sweeps are periodic, so one day can exceed that day's fees. From 2026-02-23, the first day of buybacks (dim_date.is_fee_switch_active), it is the revenue used for buybacks; before, it was held by the treasury. fees_usd minus revenue_usd is what solvers and distribution channels kept; sum that over weeks, because sweeps make single days negative.",["defillama"],0],["confidential_tvl_usd","DOUBLE","USD","Confidential Intents TVL per revenue.near.org. Self-reported by NEAR.",["revenue"],0],["is_fee_revenue_provisional","BOOLEAN","boolean","True while this day's fee and revenue columns can still change, which is until they have been read 4 nights after the day ended: the newest three days of a nightly build. revenue.near.org and DefiLlama publish a day before its data has fully arrived, then rewrite it. The page read $9,319 for 2026-11-03 and $164,920 a night later, and DefiLlama follows a night after the page. Leave these days out of trends and totals. Volume columns are not affected. The number comes from few reads (2026-10-28 to 2026-11-05), and a data test fails if a figure moves in the day's first week after the flag clears. False does not mean final for good: a later rewrite of history would show in dq_revisions.",0,0]]},"fct_intents_chain_daily":{"a":"NEAR Intents and revenue","d":"Public Intents volume per blockchain per day, from NearBlocks. From 2026-11-03 public Intents carry only a few percent of all volume, because most swaps settle confidentially; fct_dune_intents_chain_daily covers every route. NearBlocks lists Bitcoin bridged to NEAR (nbtc.bridge.near) under near; its volume and swaps are moved to btc here, as NEAR's own dashboard counts them, so near and btc differ from NearBlocks' own figures from 2026-05-06.","g":["date_day","blockchain"],"n":10845,"f":"2025-10-29","l":"2026-11-13","s":["nearblocks"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["blockchain","VARCHAR","text","Chain, as NearBlocks names it, with Bitcoin bridged to NEAR counted under btc.",0,1],["volume_usd","DOUBLE","USD","Public Intents volume.",0,0],["swaps","BIGINT","count","Swaps.",0,0]]},"fct_intents_asset_daily":{"a":"NEAR Intents and revenue","d":"Public Intents volume per asset per day, from NearBlocks. From 2026-11-03 public Intents carry only a few percent of all volume, because most swaps settle confidentially; fct_dune_intents_asset_daily covers every route. NearBlocks lists a token under the chain its contract is on, so Bitcoin bridged to NEAR (nbtc.bridge.near, which carries almost all Bitcoin swaps from 2026-05-06) is listed under near; here it is counted as btc, as NEAR's own dashboard counts it.","g":["date_day","token_id"],"n":40222,"f":"2025-11-02","l":"2026-11-13","s":["nearblocks"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["token_id","VARCHAR","token id","Token contract, or Intents asset id.",0,1],["symbol","VARCHAR","text","Token symbol.",0,0],["blockchain","VARCHAR","text","Chain the asset is counted on: NearBlocks' name for it, except that Bitcoin bridged to NEAR is btc.",0,0],["volume_token","DOUBLE","token units","Volume in token units.",0,0],["volume_usd","DOUBLE","USD","Public Intents volume.",0,0],["swaps","BIGINT","count","Swaps.",0,0]]},"fct_intents_fee_channels":{"a":"NEAR Intents and revenue","d":"Derived from NEAR's Intents dashboard on Dune: all-time gross fees per referral channel, from the table \"Total generated fees by channel\" (query 6162721). NEAR uploads the data behind it, and the page lists only the top 100 channels, 25 to a page; a reading counts only when every page was read.","g":["snapshot_date","referral"],"n":300,"f":"2026-11-01","l":"2026-11-12","s":["dune"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["referral","VARCHAR","text","Front-end or partner that sent the swap.",0,1],["fees_usd","DOUBLE","USD","All-time gross fees for this channel.",0,0],["share_of_listed_fees","DOUBLE","fraction","Share of the fees across listed channels.",0,0],["channel_rank","BIGINT","integer","Rank by fees, largest first.",0,0],["derived_from","VARCHAR","text","Credit to the dashboard and its creator.",0,0]]},"fct_intents_dashboard_readings":{"a":"NEAR Intents and revenue","d":"Derived from NEAR's Intents dashboard on Dune: headline tiles, by scope: all, public or confidential. The 2026-11-01 reading lists the tiles as displayed; later readings read each tile from the query behind it (see stg_dune_public__tiles). A tile whose response was not kept has no row for that reading: on 2026-11-10, past-day and 7-day volume for all scopes, which equal public plus confidential.","g":["snapshot_date","scope","metric"],"n":52,"f":"2026-11-01","l":"2026-11-12","s":["dune"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["scope","VARCHAR","text","all, public or confidential.",0,1],["metric","VARCHAR","text","What is being measured.",0,1],["value_usd","DOUBLE","USD","The tile's value: as displayed, rounded to whole dollars, in the 2026-11-01 reading; the query's own value in later readings. A tile over a daily series shows its latest day, the day before the reading.",0,0],["derived_from","VARCHAR","text","Credit to the dashboard and its creator.",0,0]]},"fct_dune_intents_asset_daily":{"a":"NEAR Intents and revenue","d":"Derived from NEAR's Intents dashboard on Dune: all Intents volume per asset per day, public and confidential together, over the dashboard's full history. Each dollar of a swap is counted once, and the dashboard does not say on which side. NEAR uploads the data behind the dashboard, so it is self-reported; the dashboard is read in a browser on request, so the series stops at the last reading. fct_intents_asset_daily is the public-only view from NearBlocks, and symbols differ in places, such as BTC here and NBTC there.","g":["date_day","symbol"],"n":33537,"f":"2024-12-10","l":"2026-11-11","s":["dune"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["symbol","VARCHAR","text","Asset symbol, as the dashboard names it.",0,1],["volume_usd","DOUBLE","USD","All Intents volume in this asset: public and confidential.",0,0],["share_of_day","DOUBLE","fraction","Share of that day's volume across assets.",0,0],["snapshot_date","DATE","date","Date of the reading this value comes from.",0,1],["derived_from","VARCHAR","text","Credit to the dashboard and its creator.",0,0]]},"fct_dune_intents_chain_daily":{"a":"NEAR Intents and revenue","d":"Derived from NEAR's Intents dashboard on Dune: all Intents volume per blockchain per day, public and confidential together. It is the only split of volume by chain that still covers every route, since NearBlocks sees public routes only. Each dollar of a swap is counted once, and the dashboard does not say on which side. NEAR uploads the data behind the dashboard, so it is self-reported; the dashboard is read in a browser on request, so the series stops at the last reading.","g":["date_day","blockchain"],"n":15272,"f":"2024-12-10","l":"2026-11-11","s":["dune"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["blockchain","VARCHAR","text","Blockchain code, the dashboard's in lower case, which is how NearBlocks and the Explorer write the same chains. Bitcoin bridged to NEAR is counted as btc.",0,1],["volume_usd","DOUBLE","USD","All Intents volume on this blockchain: public and confidential.",0,0],["share_of_day","DOUBLE","fraction","Share of that day's volume across blockchains.",0,0],["snapshot_date","DATE","date","Date of the reading this value comes from.",0,1],["derived_from","VARCHAR","text","Credit to the dashboard and its creator.",0,0]]},"fct_dune_intents_swaps_daily":{"a":"NEAR Intents and revenue","d":"Derived from NEAR's Intents dashboard on Dune: swaps per day across all routes, public and confidential, with the running total. NearBlocks counts public swaps only (fct_intents_daily.public_swaps), which is a small part of them from 2026-11-03. NEAR uploads the data behind the dashboard, so it is self-reported; the dashboard is read in a browser on request, so the series stops at the last reading.","g":["date_day"],"n":702,"f":"2024-12-10","l":"2026-11-11","s":["dune"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["swaps","BIGINT","count","Swaps settled that day, all routes.",0,0],["cumulative_swaps","BIGINT","count","Swaps settled up to and including that day, all routes.",0,0],["snapshot_date","DATE","date","Date of the reading this value comes from.",0,1],["derived_from","VARCHAR","text","Credit to the dashboard and its creator.",0,0]]},"fct_dune_intents_tvl_daily":{"a":"NEAR Intents and revenue","d":"Derived from NEAR's Intents dashboard on Dune: the value held in NEAR Intents per day, in public balances and in confidential ones. The two add up to the dashboard's TVL tile. NEAR uploads the data behind the dashboard, so it is self-reported; the dashboard is read in a browser on request, so the series stops at the last reading. fct_intents_daily.confidential_tvl_usd is the same confidential figure from revenue.near.org, read nightly.","g":["date_day","scope"],"n":949,"f":"2025-01-01","l":"2026-11-11","s":["dune"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["scope","VARCHAR","label","public or confidential: the kind of balance the value sits in.",0,1],["tvl_usd","DOUBLE","USD","Value held in Intents in that kind of balance.",0,0],["snapshot_date","DATE","date","Date of the reading this value comes from.",0,1],["derived_from","VARCHAR","text","Credit to the dashboard and its creator.",0,0]]},"fct_dune_intents_tvl_asset_daily":{"a":"NEAR Intents and revenue","d":"Derived from NEAR's Intents dashboard on Dune: the value held in NEAR Intents per asset per day, public and confidential balances together, from 2026-01-01. The assets add up to fct_dune_intents_tvl_daily on every day. The wNEAR row is the NEAR parked in Intents, checked against intents.near's balance on chain in dq_reconciliation. NEAR uploads the data behind the dashboard, so it is self-reported; the dashboard is read in a browser on request, so the series stops at the last reading.","g":["date_day","symbol"],"n":47880,"f":"2026-01-01","l":"2026-11-11","s":["dune"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["symbol","VARCHAR","text","Asset symbol, as the dashboard names it.",0,1],["tvl_usd","DOUBLE","USD","Value of this asset held in Intents: public and confidential balances.",0,0],["share_of_day","DOUBLE","fraction","Share of that day's value held across assets.",0,0],["snapshot_date","DATE","date","Date of the reading this value comes from.",0,1],["derived_from","VARCHAR","text","Credit to the dashboard and its creator.",0,0]]},"fct_intents_pool_chain_monthly":{"a":"NEAR Intents and revenue","d":"What the NEAR Intents contract held of named tokens at each month end, read from the chain itself and not from NEAR's dashboard, at the first block of the next UTC day, for every complete month since the contract was deployed in November 2024, and for the newest day read. It holds named tokens, not the whole pool: never add its rows up into a figure for the pool. Three kinds of token are read. wNEAR. The dollar tokens: every NEAR token the 1Click token list priced within 2% of one dollar on the day of the read. And the tokens of the pool's other main assets: every NEAR token that list names with the symbol of an asset that holds at least 1% of the pool's value on the newest day of NEAR's dashboard series and that registry/token_prices.csv lists with a price. An asset that is under 1% of the pool today is not in the table, however large it was in the past, and neither is an asset the price registry does not list or a token that has left the list, so an early month can lack what the pool held then. A listed token is read whether or not the pool holds any today. intents.near keeps public and confidential balances in its own account, so a token contract's answer about that account is the pool's whole balance of that token. A token that follows NEP-141 answers ft_balance_of; the tokens bridged through HOT are NEP-245 balances inside one contract, which answers mt_batch_balance_of. A token has no row before its contract existed. Every balance is in token units. Its value is one dollar each for a dollar token, NEAR's price for the day for wNEAR (fct_market_daily) and the asset's price in fct_token_price_daily for another asset; no price comes from NEAR's dashboard, and an asset with no price that day has an empty value. dq_reconciliation holds the wNEAR, the dollar tokens and the priced assets against the dashboard's series for the same day.","g":["date_day","asset_id"],"n":1227,"f":"2024-11-30","l":"2026-11-13","s":["rpc","dune","registry"],"c":[["date_day","DATE","date","UTC calendar day the balance closes: the last day of a month, or the newest day read.",0,1],["is_month_end","BOOLEAN","boolean","True when date_day is the last day of its month. Only the newest day read can be false.",0,0],["asset_id","VARCHAR","asset id","The token as NEAR Intents names it: nep141:<contract> for a token contract, nep245:<contract>:<token id> for a balance inside a multi-token contract. Joins stg_oneclick__tokens.asset_id.",0,1],["contract_id","VARCHAR","account id","The contract that was asked for intents.near's balance. For a nep141 asset this is the token_id of fct_wallet_holdings.",0,0],["symbol","VARCHAR","text","The token's own symbol: the registry's for wNEAR, and otherwise the 1Click list's on the day of the read, without its (DEPRECATED) mark. Several tokens share a symbol, one for each chain the asset is bridged from.",["registry"],0],["dashboard_symbol","VARCHAR","text","The asset's symbol exactly as NEAR's dashboard series writes it (fct_dune_intents_tvl_asset_daily.symbol), which is what to join a price or the dashboard's value on. It is the dashboard's symbol that equals symbol letter for letter, so the two columns read the same wherever this one is filled. Empty where the dashboard has no asset of that name.",["dune"],0],["token_class","VARCHAR","label","native_wrapped for wNEAR, stablecoin for a dollar token, other for a token of another asset that holds at least 1% of the pool on the dashboard's newest day. The classes are named tokens and do not add up to the pool.",0,0],["amount_token","DOUBLE","token units","intents.near's balance in whole tokens: the contract's answer over 10 to the power of the token's decimals, as a double. For wNEAR this is NEAR, one for one. 0 where the contract existed and the pool held none. Token units of different assets cannot be added: sum within one dashboard_symbol only.",0,0],["value_usd","DOUBLE","USD","amount_token in dollars: at one dollar each for a dollar token, at NEAR's price for the day for wNEAR, and at the asset's price in fct_token_price_daily for another asset. Empty where no price exists for that asset and day: see value_status. Its sum is the value of the named tokens read and never the pool.",0,0],["value_status","VARCHAR","label","Why value_usd is filled or empty. one_dollar: a dollar token, counted at one dollar each. near_price: wNEAR, at NEAR's price for the day in fct_market_daily. token_price: another asset, at its price for the day in fct_token_price_daily, joined on dashboard_symbol and date_day. no_price: no price exists for that asset and day, so the value is empty; no price is typed or guessed here.",0,0],["block_height","BIGINT","block","The block read: the first of the next UTC day, as in dim_block_day.",0,0],["snapshot_date","DATE","date","Snapshot the token's balance for the day was read in. Past blocks do not change, so a later read gives the same balance.",0,1]]},"fct_dune_dashboard_results":{"a":"NEAR Intents and revenue","d":"Every row of every Dune widget or query read so far, as returned, so nothing waits for a typed table. Readings of NEAR's public Intents dashboard in a browser have read_via browser. Query results through Dune's official API have read_via api, once a DUNE_API_KEY with API access has run. NEAR uploads the data behind the dashboard, so it is self-reported.","g":["snapshot_date","reading_id","row_index"],"n":207060,"f":"2026-11-01","l":"2026-11-12","s":["dune"],"c":[["snapshot_date","DATE","date","Date the widget was read.",0,1],["reading_id","VARCHAR","text","The widget: query id, dashboard filter values, the row offset of a table page after the first, and a hash of the columns asked for. A table read page by page has one reading_id per page. For a query read through the API, <query id>__api.",0,1],["query_id","BIGINT","Dune query id","Dune query behind the widget.",0,0],["query_title","VARCHAR","text","Query title, where registry/dune_queries.csv lists it.",0,0],["query_url","VARCHAR","URL","Public page of the query on Dune.",0,0],["selection","VARCHAR","text","Dashboard filter values in force, such as blockchain-ALL__symbol-ALL. Empty for a query read through the API.",0,0],["generated_at","TIMESTAMP","UTC timestamp","When Dune generated the stored result.",0,1],["is_complete","BOOLEAN","boolean","False when the rows read, across all pages of a table, are only part of the query's rows. A tile asks for one row of a longer result, so it is false for most tiles.",0,0],["row_index","BIGINT","integer","Position of the row in the result, from 1, counted across a table's pages.",0,1],["row_json","VARCHAR","JSON text","The row as JSON, with the query's own column names.",0,0],["read_via","VARCHAR","text","browser for a reading of the dashboard page in a browser, on request and never on a schedule, by a person or by an AI-driven browser at the owner's request (the manifest note says which); api for a query read through Dune's API.",0,0],["derived_from","VARCHAR","text","Credit to the dashboard and its creator, or to the query's creator for an API read.",0,0]]},"fct_intents_1click_daily":{"a":"NEAR Intents and revenue","d":"1Click per UTC day, from the Intents Explorer API. 1Click is one route into NEAR Intents, so its volume is part of the total in fct_intents_daily. Tallied per day, with no row or wallet address stored. The history is complete from the first day with a swap, 2025-03-27. A day with no swap leaves no row, and ten days in April and May 2025 had none, so is_in_daily_run is true from 2025-05-19: where a sum must not skip a day, use only rows where it is true. Empty until INTENTS_EXPLORER_JWT is set and a snapshot is in the build.","g":["date_day"],"n":587,"f":"2025-03-27","l":"2026-11-13","s":["explorer"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["swaps","BIGINT","count","Swaps created that day, in every status.",0,0],["finished_swaps","HUGEINT","count","Swaps with status SUCCESS.",0,0],["refunded_swaps","HUGEINT","count","Swaps with status REFUNDED.",0,0],["volume_usd","DOUBLE","USD","Value paid in on finished swaps.",0,0],["amount_out_usd","DOUBLE","USD","Value paid out on finished swaps.",0,0],["app_fees_usd","DOUBLE","USD","App fees on finished swaps: appFees read as basis points of the value paid in.",0,0],["senders","BIGINT","count","Distinct sending wallets on finished swaps. Only the count is stored. Empty before 2026, where the Explorer's rows carry no sender.",0,0],["recipients","BIGINT","count","Distinct receiving wallets on finished swaps. Only the count is stored.",0,0],["share_of_all_intents_volume","DOUBLE","fraction","volume_usd divided by fct_intents_daily.volume_usd: all of Intents that day, across every route, confidential included.",0,0],["is_in_daily_run","BOOLEAN","boolean","True from the day after the newest missing day, so every day from there to the newest is present: from 2025-05-19 at the 2026-11-10 pin, by when every day back to 2024-11-01 had been walked. The ten missing days before it, from 2025-04-05 to 2025-05-18, had no 1Click swap, and such a day leaves no row; the rows before 2025-05-19 are real days as well. While a backfill is still running, a missing day is one not tallied yet. The other fct_intents_1click tables carry the same flag.",0,0]]},"fct_intents_1click_channel_daily":{"a":"NEAR Intents and revenue","d":"1Click swaps per UTC day, referral channel and status, from the Intents Explorer API, with volume and app fees for finished swaps. A swap that was refunded, failed or is still processing keeps its count and has no USD value: the Explorer's figure for it is the amount asked for, which nothing checks, and one refunded swap on 2026-07-28 reads $29.99 trillion. Silver (stg_intents_explorer__channels) keeps those figures as tallied. Empty until a snapshot with INTENTS_EXPLORER_JWT is in the build.","g":["date_day","referral","status"],"n":34694,"f":"2025-03-27","l":"2026-11-13","s":["explorer"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["referral","VARCHAR","text","Front-end or partner that sent the swap, or (none).",0,1],["status","VARCHAR","text","Swap status per the Explorer API: SUCCESS, REFUNDED, FAILED or PROCESSING.",0,1],["swaps","BIGINT","count","Swaps.",0,0],["amount_in_usd","DOUBLE","USD","Value paid in. Empty unless status is SUCCESS.",0,0],["amount_out_usd","DOUBLE","USD","Value paid out. Empty unless status is SUCCESS.",0,0],["app_fee_usd","DOUBLE","USD","App fees: appFees read as basis points of the value paid in. Empty unless status is SUCCESS.",0,0],["is_in_daily_run","BOOLEAN","boolean","True where the day belongs to the unbroken run of recent days, false for a day sampled alone, one a week: see fct_intents_1click_daily.is_in_daily_run. Sum or average only where this is true.",0,0]]},"fct_intents_1click_pair_daily":{"a":"NEAR Intents and revenue","d":"Finished 1Click swaps per UTC day and asset pair, from the Intents Explorer API. Pairs under $1,000 on a day are summed into one (other) row, so each day's total stays right.","g":["date_day","origin_asset","destination_asset"],"n":182104,"f":"2025-03-27","l":"2026-11-13","s":["explorer"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["origin_asset","VARCHAR","asset id","Asset paid in, or (other).",0,1],["origin_symbol","VARCHAR","text","Symbol of the asset paid in, per the 1Click token list, without the (DEPRECATED) mark 1Click adds to a token it has replaced.",0,0],["origin_blockchain","VARCHAR","text","Chain of the asset paid in, per the 1Click token list.",0,0],["destination_asset","VARCHAR","asset id","Asset paid out, or (other).",0,1],["destination_symbol","VARCHAR","text","Symbol of the asset paid out, per the 1Click token list, without the (DEPRECATED) mark 1Click adds to a token it has replaced.",0,0],["destination_blockchain","VARCHAR","text","Chain of the asset paid out, per the 1Click token list.",0,0],["swaps","BIGINT","count","Finished swaps.",0,0],["amount_in_usd","DOUBLE","USD","Value paid in.",0,0],["amount_out_usd","DOUBLE","USD","Value paid out.",0,0],["is_in_daily_run","BOOLEAN","boolean","True where the day belongs to the unbroken run of recent days, false for a day sampled alone, one a week: see fct_intents_1click_daily.is_in_daily_run. Sum or average only where this is true.",0,0]]},"fct_intents_1click_route_daily":{"a":"NEAR Intents and revenue","d":"Finished 1Click swaps per UTC day, by how funds came in and went out, from the Intents Explorer API. These are the user's legs, not where the swap settled: from 2026-11-03 most 1Click volume settles confidentially, since it is more than all public Intents volume, while its legs still read ORIGIN_CHAIN and DESTINATION_CHAIN.","g":["date_day","deposit_type","recipient_type"],"n":2052,"f":"2025-03-27","l":"2026-11-13","s":["explorer"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["deposit_type","VARCHAR","text","How funds came in: ORIGIN_CHAIN, INTENTS or CONFIDENTIAL_INTENTS.",0,1],["recipient_type","VARCHAR","text","How funds went out: DESTINATION_CHAIN, INTENTS or CONFIDENTIAL_INTENTS.",0,1],["swaps","BIGINT","count","Finished swaps.",0,0],["amount_in_usd","DOUBLE","USD","Value paid in.",0,0],["is_in_daily_run","BOOLEAN","boolean","True where the day belongs to the unbroken run of recent days, false for a day sampled alone, one a week: see fct_intents_1click_daily.is_in_daily_run. Sum or average only where this is true.",0,0]]},"fct_intents_1click_size_daily":{"a":"NEAR Intents and revenue","d":"Finished 1Click swaps per UTC day and size band, from the Intents Explorer API.","g":["date_day","size_band"],"n":2701,"f":"2025-03-27","l":"2026-11-13","s":["explorer"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["size_band","VARCHAR","text","Value paid in, in USD: under_100, 100_to_1k, 1k_to_10k, 10k_to_100k or 100k_and_over.",0,1],["swaps","BIGINT","count","Finished swaps.",0,0],["amount_in_usd","DOUBLE","USD","Value paid in.",0,0],["is_in_daily_run","BOOLEAN","boolean","True where the day belongs to the unbroken run of recent days, false for a day sampled alone, one a week: see fct_intents_1click_daily.is_in_daily_run. Sum or average only where this is true.",0,0]]},"fct_intents_1click_fee_recipient_daily":{"a":"NEAR Intents and revenue","d":"App fees on finished 1Click swaps per UTC day and recipient, from the Intents Explorer API. A recipient is named only if registry/entities.csv lists it; every other recipient is summed into (other).","g":["date_day","recipient"],"n":1318,"f":"2025-05-06","l":"2026-11-13","s":["explorer"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["recipient","VARCHAR","account id","Registry account paid the fee, or (other).",0,1],["entries","BIGINT","count","Fee entries paid to this recipient.",0,0],["fee_usd","DOUBLE","USD","Fees: appFees read as basis points of the value paid in.",0,0],["is_in_daily_run","BOOLEAN","boolean","True where the day belongs to the unbroken run of recent days, false for a day sampled alone, one a week: see fct_intents_1click_daily.is_in_daily_run. Sum or average only where this is true.",0,0]]},"fct_revenue_capture":{"a":"NEAR Intents and revenue","d":"Share of gross fees captured as revenue, per mechanism and window, as NEAR publishes it.","g":["snapshot_date","mechanism","time_window"],"n":168,"f":"2026-11-01","l":"2026-11-14","s":["revenue"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["mechanism","VARCHAR","text","How the fee is collected: front_end, b2b_partners or quote_improvement.",0,1],["time_window","VARCHAR","text","d7, d30, ytd or all_time.",0,1],["capture_rate","DOUBLE","fraction","Share of gross fees captured as net revenue.",0,0]]},"fct_revenue_page_emissions":{"a":"NEAR Intents and revenue","d":"NEAR's own year-to-date revenue and emissions. Kept apart from fct_supply_daily so the two can be compared. The page's percentages are these NEAR amounts over reference_supply_near, so they are not repeated here.","g":["date_day"],"n":317,"f":"2026-01-01","l":"2026-11-13","s":["revenue"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["emissions_ytd_near","DOUBLE","NEAR","Emissions this year per revenue.near.org.",0,0],["revenue_ytd_near","DOUBLE","NEAR","Revenue this year per revenue.near.org.",0,0],["reference_supply_near","DOUBLE","NEAR","Supply the page divides by: total supply at the end of the day before the read, one figure for every day of a read. So each read moves every past percentage slightly, by about 0.0001 points a night.",0,0]]},"fct_revenue_page_monthly":{"a":"NEAR Intents and revenue","d":"NEAR's own monthly revenue series. The newest month may be incomplete. The page's running totals equal the sums of these months, so they are not repeated here.","g":["month_start"],"n":16,"f":"2025-08-01","l":"2026-11-01","s":["revenue"],"c":[["month_start","DATE","date","First day of the month.",0,1],["revenue_usd","DOUBLE","USD","Revenue that month per revenue.near.org.",0,0],["revenue_near","DOUBLE","NEAR","Revenue that month in NEAR per revenue.near.org.",0,0]]},"fct_wallet_transfers":{"a":"Wallets","d":"Every transfer touching a crawled wallet. Amounts are signed from the wallet's point of view, so outflows are negative. The day the newest crawl ran on is left out until the next crawl, like every daily series.","g":["account_id","block_height","transaction_id","receipt_id","action_index","log_index","transfer_index","asset_id","amount_raw"],"n":12277,"f":"2020-07-22","l":"2026-11-13","s":["fastnear"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["block_height","BIGINT","blocks","Block height.",0,1],["block_timestamp_ns","HUGEINT","nanoseconds since epoch","Block timestamp.",0,0],["account_id","VARCHAR","account id","NEAR account.",0,1],["account_entity","VARCHAR","text","Entity of the wallet.",0,0],["direction","VARCHAR","text","in or out, from the wallet's point of view.",0,0],["counterparty_id","VARCHAR","account id","The other account in the transfer.",0,0],["counterparty_entity","VARCHAR","text","Entity of the counterparty, if it is in the registry.",["registry"],0],["counterparty_category","VARCHAR","text","Category of the counterparty, if it is in the registry.",["registry"],0],["is_between_revenue_wallets","BOOLEAN","boolean","Both sides are revenue wallets, so no new revenue arrived.",0,0],["asset_id","VARCHAR","asset id","Asset, such as native:near or nep141:wrap.near.",0,1],["asset_type","VARCHAR","text","Near, Ft or Mt.",0,0],["transfer_type","VARCHAR","text","Kind of transfer per FastNear.",0,0],["method_name","VARCHAR","text","Contract method, if any.",0,0],["amount_raw","VARCHAR","raw units","Signed amount in the token's smallest unit, as a string so no digits are lost.",0,1],["amount_token","DOUBLE","token units","Signed amount in whole tokens.",0,0],["amount_usd","DOUBLE","USD","Signed value: FastNear's at transfer time where it gives one, which it does for some transfers only; otherwise, for native NEAR and wNEAR, amount_token times the day's closing price from fct_market_daily. Other tokens stay empty. usd_basis says which. Where FastNear gave a value, the close-price figure was within 1.9% of it on the median transfer and within 7.7% on nine in ten.",0,0],["usd_basis","VARCHAR","text","transfer_time where amount_usd is FastNear's, daily_close where it is the amount at the day's closing price, empty where there is neither.",0,0],["transaction_id","VARCHAR","hash","Transaction hash. Empty for protocol transfers with no transaction, such as epoch rewards to treasury.near.",0,1],["receipt_id","VARCHAR","hash","Receipt id.",0,1],["action_index","INTEGER","integer","Action position in the receipt.",0,1],["log_index","INTEGER","integer","Log position in the receipt.",0,1],["transfer_index","BIGINT","integer","FastNear's transfer position.",0,1],["signer_id","VARCHAR","account id","Transaction signer.",0,0],["predecessor_id","VARCHAR","account id","Account that sent the receipt.",0,0]]},"fct_wallet_flows_daily":{"a":"Wallets","d":"Transfers summed per wallet, day, asset and direction, with hops between revenue wallets split out.","g":["date_day","account_id","asset_id","direction","is_between_revenue_wallets"],"n":3263,"f":"2020-07-22","l":"2026-11-13","s":["fastnear"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["account_id","VARCHAR","account id","NEAR account.",0,1],["asset_id","VARCHAR","asset id","Asset, such as native:near or nep141:wrap.near.",0,1],["direction","VARCHAR","text","in or out, from the wallet's point of view.",0,1],["is_between_revenue_wallets","BOOLEAN","boolean","Both sides are revenue wallets, so no new revenue arrived.",0,1],["transfers","BIGINT","count","Transfers.",0,0],["counterparties","BIGINT","count","Distinct counterparties.",0,0],["amount_token","DOUBLE","token units","Signed amount in whole tokens.",0,0],["amount_usd","DOUBLE","USD","Signed value summed over the transfers: FastNear's figure where there is one, else the day's closing price for NEAR and wNEAR; see fct_wallet_transfers.usd_basis. Other tokens without FastNear's figure add nothing.",0,0]]},"fct_wallet_counterparties":{"a":"Wallets","d":"Who each crawled wallet deals with. Counterparties outside the registry stay unlabelled until there is evidence of who they are, so an empty entity means unknown, not unimportant.","g":["account_id","counterparty_id"],"n":180,"f":null,"l":null,"s":["fastnear"],"c":[["account_id","VARCHAR","account id","Crawled wallet.",0,1],["counterparty_id","VARCHAR","account id","The other account.",0,1],["counterparty_entity","VARCHAR","text","Entity of the counterparty, if it is in the registry.",["registry"],0],["counterparty_category","VARCHAR","text","Category of the counterparty, if it is in the registry.",["registry"],0],["transfers","BIGINT","count","Transfers between the two.",0,0],["usd_in","DOUBLE","USD","Value received by the wallet: FastNear's at transfer time where it gives one, else the day's close for NEAR and wNEAR.",0,0],["usd_out","DOUBLE","USD","Value sent by the wallet, valued as usd_in, as a positive number.",0,0],["first_seen","DATE","date","First transfer between the two.",0,1],["last_seen","DATE","date","Latest transfer between the two.",0,1]]},"fct_revenue_inflows_daily":{"a":"Wallets","d":"NEAR's captured revenue rebuilt from wallet transfers using DefiLlama's published method: NEAR and wNEAR received by the three revenue wallets, excluding hops between them. An independent check that needs no NEAR-uploaded data.","g":["date_day","account_id"],"n":515,"f":"2025-09-22","l":"2026-11-13","s":["fastnear"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["account_id","VARCHAR","account id","NEAR account.",0,1],["transfers","BIGINT","count","Transfers.",0,0],["received_near","DOUBLE","NEAR","NEAR and wNEAR received.",0,0],["received_usd","DOUBLE","USD","Value received: FastNear's at transfer time where it gives one, else the day's closing price; see fct_wallet_transfers.usd_basis.",0,0]]},"fct_wallet_balance_daily":{"a":"Wallets","d":"Native NEAR balance per crawled wallet per day: the last running balance FastNear reports that day, carried forward over days without transfers. dq_reconciliation compares it with NearBlocks' own balance series.","g":["date_day","account_id"],"n":5000,"f":"2020-07-22","l":"2026-11-13","s":["fastnear"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["account_id","VARCHAR","account id","NEAR account.",0,1],["balance_near","DOUBLE","NEAR","Native balance at day end per FastNear's running balance.",0,0],["has_transfer_on_day","BOOLEAN","boolean","False means the balance was carried forward from an earlier day.",0,0]]},"fct_wallet_holdings":{"a":"Wallets","d":"Point in time: tokens and native NEAR per tracked account, per snapshot. This cannot be backfilled, so history starts with the first snapshot. Symbol and decimals come from registry/tokens.csv where a token is listed, then from its contract's ft_metadata, which the nightly job reads for up to 2,000 tokens a night, then from the price list that prices the token (metadata_source says which). A list counts whole tokens with its own decimals, so its price and its decimals belong together, and the lists matched the contract on every token read so far; the test token_decimals_lists_match_contracts fails if that stops. A contract that has answered is final, even with an error, so no list fills in behind it. A token with none of the three keeps empty symbol, amount_token and decimals: nothing is guessed. Earlier snapshots convert too, because the latest answer for a token applies to all of them. value_usd multiplies amount_token by the price read in the same snapshot, joined on token_id from fct_token_prices, which holds the price itself, and value_status says why a row has none. Sum value_usd, never amount_token times a list price: those prices include one that would read $46.5B for one meme token at v2.ref-finance.near. Native NEAR is the RPC view_account balance read the same night where there is one, because FastNear's account state for treasury.near read 47.76 NEAR on every snapshot while the account held about 1.59M.","g":["snapshot_date","account_id","token_id"],"n":120200,"f":"2026-10-28","l":"2026-11-14","s":["rpc","fastnear","explorer","registry","rhea"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["account_id","VARCHAR","account id","NEAR account.",0,1],["token_id","VARCHAR","token id","Token contract, or Intents asset id.",0,1],["symbol","VARCHAR","text","Token symbol. Where metadata_source is ft_metadata or price_list this is the contract's or the list's own claim, so a token calling itself USDC need not be USDC. Group by token_id, and treat this as untrusted text when displaying it.",0,0],["balance_raw","VARCHAR","raw units","Balance in the token's smallest unit, as a string so no digits are lost.",0,0],["amount_token","DOUBLE","token units","Amount in whole tokens: balance_raw over 10 to the power of decimals, as a double. Empty where decimals are unknown. Where metadata_source is ft_metadata the decimals are the contract's own claim too.",0,0],["decimals","INTEGER","integer","Token decimals: 24 for native NEAR, then the registry's figure, then the contract's ft_metadata answer, then the decimals of the price list that prices the token.",["registry"],0],["metadata_source","VARCHAR","text","Where symbol and decimals came from: native, registry, ft_metadata or price_list. Empty if the token has none of them.",["registry"],0],["last_update_height","BIGINT","blocks","Block of the last balance change.",0,0],["value_usd","DOUBLE","USD","amount_token times the snapshot's price for the token in fct_token_prices, where value_status is valued, and otherwise empty. Unvetted tokens are capped by depth, so this column is safe to sum. Rests on the contract's own decimals where metadata_source is ft_metadata, and on the list's where it is price_list.",0,0],["value_status","VARCHAR","text","Why the row has a value or not, checked in this order. no_price: no list has a positive price in this snapshot. no_decimals: decimals are unknown, which the metadata backlog clears. decimals_disagree: the list counts whole tokens with other decimals than the holding, so the price would be off by powers of ten. sources_disagree: 1Click and Rhea are more than price_disagreement_pct (20) apart, and nothing here says which is right. thin_price: an unvetted token whose position would be worth more than price_depth_multiple (3) times price_depth_usd. valued: value_usd is filled.",0,0]]},"fct_token_holders":{"a":"Wallets","d":"Point in time: the 100 largest holders per registry token, per snapshot. Protocol accounts are labelled; other holders stay unlabelled because this warehouse does not try to identify individuals.","g":["snapshot_date","token_id","holder_account_id"],"n":12300,"f":"2026-11-01","l":"2026-11-14","s":["fastnear"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["token_id","VARCHAR","token id","Token contract, or Intents asset id.",0,1],["symbol","VARCHAR","text","Token symbol.",0,0],["holder_rank","BIGINT","integer","Rank by balance, largest first.",0,0],["holder_account_id","VARCHAR","account id","Holder account.",0,1],["holder_entity","VARCHAR","text","Entity of the holder, if it is in the registry.",["registry"],0],["holder_category","VARCHAR","text","Category of the holder, if it is in the registry.",["registry"],0],["balance_raw","VARCHAR","raw units","Balance in the token's smallest unit, as a string so no digits are lost.",0,0],["amount_token","DOUBLE","token units","Signed amount in whole tokens.",0,0],["share_of_top_100","DOUBLE","fraction","Share of the balance held by the top 100. Not a share of total supply.",0,0]]},"fct_validator_epoch":{"a":"Security and staking","d":"Validator set per epoch, for the epoch in force at the first block of each UTC day plus the current epoch read each night. NEAR runs about three epochs a day, so this is a daily sample of epochs, not every epoch. Past epochs are backfilled newest first from the archival node. Its nodes do not all hold the same epochs, so an epoch one of them refuses is asked again on later runs; at the 2026-11-10 pin every day from 2025-01-01 has its epoch. An epoch read after it ended has final production counts; a nightly read of the current epoch is partial.","g":["epoch_height","validator_account_id"],"n":238858,"f":null,"l":null,"s":["rpc"],"c":[["epoch_height","BIGINT","integer","Epoch number.",0,1],["epoch_start_height","BIGINT","blocks","First block of the epoch.",0,0],["validator_account_id","VARCHAR","account id","Validator pool account.",0,1],["stake_near","DOUBLE","NEAR","Stake.",0,0],["stake_share","DOUBLE","fraction","Share of the epoch's total stake.",0,0],["stake_rank","BIGINT","integer","Rank by stake, largest first.",0,0],["blocks_produced","BIGINT","count","Blocks produced. Like the five counts after it, final only where is_epoch_complete is true; for an epoch read in progress it stops where the read happened.",0,0],["blocks_expected","BIGINT","count","Blocks expected.",0,0],["chunks_produced","BIGINT","count","Chunks produced.",0,0],["chunks_expected","BIGINT","count","Chunks expected.",0,0],["endorsements_produced","BIGINT","count","Chunk endorsements produced.",0,0],["endorsements_expected","BIGINT","count","Chunk endorsements expected.",0,0],["read_from","VARCHAR","text","nightly for a mid-epoch read, archival for an epoch read after it ended.",0,0],["is_epoch_complete","BOOLEAN","boolean","True when the epoch had ended at the read, so its production counts are final: the validators' expected blocks add up to the protocol's epoch length (43,200), since every block has one expected producer. False for an epoch the nightly read caught in progress. The backfill reads each such epoch again once it has ended, so only the newest epoch stays false: at the 2026-11-10 pin 688 of 689 epochs were complete, and the one in progress had run 12,907 blocks. The stake columns do not depend on it: stakes are fixed when an epoch starts.",0,0]]},"fct_validator_summary":{"a":"Security and staking","d":"Decentralization per epoch: validator count, stake concentration and Nakamoto coefficients. One epoch per day, the one in force at the day's first block, plus the current epoch read each night: see fct_validator_epoch. History is backfilled newest first; at the 2026-11-10 pin every day from 2025-01-01 has its epoch.","g":["epoch_height"],"n":697,"f":null,"l":null,"s":["rpc"],"c":[["epoch_height","BIGINT","integer","Epoch number.",0,1],["epoch_start_height","BIGINT","blocks","First block of the epoch.",0,0],["validators","BIGINT","count","Validators in the epoch. It moves by a dozen or more from one epoch to the next, because pools that are offline are kicked out and return on their standing stake: epochs 4944, 4947, 4948 and 4950 read 335, 352, 339 and 352 on the chain itself (checked 2026-11-10). Stake-weighted measures are steadier.",0,0],["total_stake_near","DOUBLE","NEAR","Total stake.",0,0],["top_validator_share","DOUBLE","fraction","Largest validator's share of stake.",0,0],["top_10_share","DOUBLE","fraction","Ten largest validators' share of stake.",0,0],["stake_hhi","DOUBLE","index 0 to 1","Herfindahl index of stake shares: 0 is even, 1 is one validator.",0,0],["nakamoto_33","BIGINT","count","Fewest validators holding over one third of stake, the share that can halt finality.",0,0],["nakamoto_67","BIGINT","count","Fewest validators holding over two thirds of stake.",0,0],["blocks_counted","HUGEINT","blocks","Blocks of the epoch the read covers: the validators' expected blocks added up. 43,200, the epoch length, or a few more for an epoch read after it ended; fewer for one read in progress.",0,0],["is_epoch_complete","BOOLEAN","boolean","True when the epoch had ended at the read: see fct_validator_epoch.is_epoch_complete. Every measure in this table holds either way, because stakes are fixed when an epoch starts.",0,0],["approx_date_day","DATE","date","Date of the epoch's start, from the nearest daily block. Empty if none is within a day. Not a key: an epoch lasts about seven hours, so one day can hold two rows, and does wherever both the nightly read and the backfill caught an epoch that started that day. To chart by day, take one row per day or average them.",0,1],["staking_ratio","DOUBLE","fraction","total_stake_near divided by total supply in the nearest earlier daily block (dim_block_day).",0,0]]},"fct_chain_signatures_daily":{"a":"Security and staking","d":"Chain Signatures activity per day, from NearBlocks' signer statistics.","g":["date_day"],"n":378,"f":"2025-11-01","l":"2026-11-13","s":["nearblocks"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["txns","BIGINT","count","Transactions to the signer contract. fct_contract_daily has the same count for v1.signer from NearBlocks' account statistics, which dq_reconciliation checks.",0,0],["signers","BIGINT","count","Distinct accounts requesting signatures.",0,0],["gas_burnt","HUGEINT","gas units","Gas burnt by the signer contract.",0,0]]},"fct_mpc_state":{"a":"Security and staking","d":"Chain Signatures contract state per day, read directly from v1.signer. Daily from 2025-01-01, read at the first block of each UTC day from the archival node, and one day a month before that, back to the contract's first month. A day on which the contract was not in its Running state has no row.","g":["snapshot_date"],"n":687,"f":"2024-09-01","l":"2026-11-14","s":["rpc"],"c":[["snapshot_date","DATE","date","The UTC date of the block the values were read at. With read_from = archival that is the day's first block, so the row shows the state as the day began, which is the close of the day before. With read_from = nightly it is the tip when that date's snapshot ran, some hours into the day.",0,1],["participants","HUGEINT","count","MPC participants.",0,0],["threshold","INTEGER","count","Signers required.",0,0],["signature_domains","HUGEINT","count","Signature schemes supported: the contract's list of domains. Its first version had no such list and held a single key, which counts as 1.",0,0],["keyset_epoch","BIGINT","integer","MPC key generation epoch.",0,0],["read_from","VARCHAR","label","archival: replayed from the archival node at the first block of the UTC day. nightly: read at the tip when the snapshot of that date ran, used only for a date the replay has not read. All of a contract's figures on a date come from the same read.",0,0]]},"fct_mpc_participants":{"a":"Security and staking","d":"MPC operators per day, read directly from v1.signer. Daily from 2025-01-01, read at the first block of each UTC day from the archival node, and one day a month before that, back to the contract's first month. A day on which the contract was not in its Running state has no rows.","g":["snapshot_date","operator_account_id"],"n":6716,"f":"2024-09-01","l":"2026-11-14","s":["rpc"],"c":[["snapshot_date","DATE","date","The UTC date of the block the values were read at. With read_from = archival that is the day's first block, so the row shows the state as the day began, which is the close of the day before. With read_from = nightly it is the tip when that date's snapshot ran, some hours into the day.",0,1],["operator_account_id","VARCHAR","account id","MPC operator account.",0,1],["participant_id","INTEGER","integer","Operator's id in the contract.",0,0],["read_from","VARCHAR","label","archival: replayed from the archival node at the first block of the UTC day. nightly: read at the tip when the snapshot of that date ran, used only for a date the replay has not read. All of a contract's figures on a date come from the same read.",0,0]]},"fct_mpc_operators":{"a":"Security and staking","d":"MPC operators as NearBlocks reports them, per snapshot: the list and each node's address. The operator list and the threshold are the contract's, in fct_mpc_participants and fct_mpc_state: a data test holds NearBlocks' list to the contract's, and dq_reconciliation its threshold. NearBlocks also serves a validator mark and three TEE fields, which have held no value on any read (false, none and empty) and say nothing either way about whether a node runs in a TEE, so they stay in silver; a data test says when one starts to carry a value.","g":["snapshot_date","operator_account_id"],"n":221,"f":"2026-11-01","l":"2026-11-14","s":["nearblocks"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["operator_account_id","VARCHAR","account id","MPC operator account.",0,1],["node_url","VARCHAR","url","Operator's public node address.",0,0]]},"fct_lst_snapshot":{"a":"Security and staking","d":"Liquid staking per day, read directly from each contract (LiNEAR, stNEAR, rNEAR). Daily from 2025-01-01, read at the first block of each UTC day from the archival node, and one day a month before that, back to each contract's first month. A token has no row before its contract existed.","g":["snapshot_date","token"],"n":1908,"f":"2021-09-01","l":"2026-11-14","s":["rpc"],"c":[["snapshot_date","DATE","date","The UTC date of the block the values were read at. With read_from = archival that is the day's first block, so the row shows the state as the day began, which is the close of the day before. With read_from = nightly it is the tip when that date's snapshot ran, some hours into the day.",0,1],["token","VARCHAR","text","Liquid staking token.",0,1],["contract","VARCHAR","account id","Token contract.",0,0],["price_near","DOUBLE","NEAR per token","NEAR redeemable per token.",0,0],["token_supply","DOUBLE","token units","Tokens outstanding.",0,0],["delegated_near","DOUBLE","NEAR","NEAR the contract has staked with validators, read from the contract. Where a read holds no get_total_staked_balance for rNEAR, this is token_supply times price_near, which is the same figure because a contract sets its price as staked NEAR divided by supply: a data test holds the two within 0.01% wherever both exist.",0,0],["read_from","VARCHAR","label","archival: replayed from the archival node at the first block of the UTC day. nightly: read at the tip when the snapshot of that date ran, used only for a date the replay has not read. All of a contract's figures on a date come from the same read.",0,0]]},"fct_protocol_tvl_daily":{"a":"Capital and DeFi","d":"TVL on NEAR per protocol per day, excluding exchange wallets. A protocol is one DefiLlama id, so a rename, which changes the slug and keeps the id, joins the old slug's days to the new slug's and counts the protocol once. A protocol missing from the newest reading keeps its history and its days stop, because a missed night and a delisting look the same. Two ids carrying one series fail the test no_two_protocols_share_a_tvl_series. Liquid staking and lending can count the same NEAR twice, so do not sum categories into a chain total. DefiLlama can rewrite TVL history without notice, as it did for Ethereum and Solana on 2026-11-03 (see fct_peer_daily.tvl_usd), so no value here is final either, although no protocol on NEAR had moved through 2026-11-05. Two rows are not histories: near-intents begins on 2025-10-30 and carried well under the public pool until September 2026 (8% to 45% of it by monthly median through August, 101% to 133% in October), so read the pool from fct_dune_intents_tvl_daily, and near-bridge begins on 2026-08-26 and steps from about $9M to about $50M in late September. Rhea Lend's row halves and comes back on some days; fct_defi_tvl_daily marks them. On 2026-11-09, $130.5M of liquid staking tokens sat in Rhea's lending market and DEX and was counted under Liquid Staking and again under Lending or Dexs.","g":["date_day","protocol_id"],"n":16921,"f":"2021-08-20","l":"2026-11-13","s":["defillama"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["protocol_id","VARCHAR","id","DefiLlama's id for the protocol. It stays the same when the protocol is renamed.",0,1],["protocol_slug","VARCHAR","id","DefiLlama's URL name for the protocol, as of the newest reading that listed it. It can change.",0,0],["protocol_name","VARCHAR","text","Protocol name.",0,0],["category","VARCHAR","text","DefiLlama category.",0,0],["tvl_usd","DOUBLE","USD","Total value locked.",0,0]]},"fct_defi_tvl_daily":{"a":"Capital and DeFi","d":"DefiLlama's TVL for the NEAR chain per day, with the same figure counted in NEAR and a flag for fault days. The figure is fct_peer_daily.tvl_usd for NEAR: what sits in lending markets, DEXs and restaking. It leaves out liquid staking, bridges, tokenised assets and exchange wallets, and each day's value is the state as that day began, so tvl_in_near divides it by NEAR's close on the day before. On a fault day DefiLlama's reading of Rhea Lend, the largest protocol in the figure, falls to about half and later comes back while NEAR's price and the staking tokens held in it do not move; leave those days out of a chart, and take a week's or month's level from its last clean day. The rule cannot tell a fault from a real fall that reverses within a month: the sixteen days from 2025-09-07 are read as a fault. The dollar figure follows NEAR's price, because most of what the protocols hold is NEAR or staked NEAR, so read growth in tvl_in_near.","g":["date_day"],"n":1912,"f":"2021-08-20","l":"2026-11-13","s":["defillama","nearblocks","coinmetrics","coinbase","rpc","fastnear"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["tvl_usd","DOUBLE","USD","DefiLlama's TVL for the NEAR chain as the day began: fct_peer_daily.tvl_usd.",["defillama"],0],["near_price_day_before_usd","DOUBLE","USD","NEAR's close on the day before, the price the day's TVL was counted at.",0,0],["tvl_in_near","DOUBLE","NEAR","tvl_usd over near_price_day_before_usd: the figure counted in NEAR, so a move in NEAR's price does not move it.",0,0],["rhea_lend_tvl_usd","DOUBLE","USD","DefiLlama's TVL for Rhea Lend on the day. Empty before the protocol's first day, 2022-03-14.",0,0],["rhea_lend_tvl_in_near","DOUBLE","NEAR","rhea_lend_tvl_usd over near_price_day_before_usd.",0,0],["rhea_lend_usual_in_near","DOUBLE","NEAR","Median of rhea_lend_tvl_in_near over the 61 days centred on the day. At the newest days the window holds fewer later days.",0,0],["is_fault","BOOLEAN","flag","True when rhea_lend_tvl_in_near is under 75% of rhea_lend_usual_in_near and Rhea Lend has 30 days of history. Such a day's tvl_usd is not a real fall in what NEAR's DeFi holds.",0,0]]},"fct_exchange_balance_daily":{"a":"Capital and DeFi","d":"Assets on NEAR in the wallets DefiLlama attributes to centralised exchanges, in USD, per exchange per day. DefiLlama leaves these wallets out of chain TVL and so does fct_protocol_tvl_daily; here they stand on their own. The figure is every asset in the listed wallets at DefiLlama's prices, so it is mostly NEAR and moves with NEAR's price. Only wallets DefiLlama has labelled count, so an exchange's unlabelled wallets are missing and a relabelling moves the whole series. History is fetched for the largest 25 protocols on NEAR, so a small exchange can have a row in dim_protocol and no days here. Like all DefiLlama history, it can be rewritten without notice.","g":["date_day","protocol_id"],"n":5955,"f":"2022-11-14","l":"2026-11-13","s":["defillama"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["protocol_id","VARCHAR","id","DefiLlama's id for the exchange. It stays the same when the exchange is renamed.",0,1],["exchange_slug","VARCHAR","id","DefiLlama's URL name for the exchange, as of the newest reading that listed it.",0,0],["exchange_name","VARCHAR","text","Exchange name.",0,0],["balance_usd","DOUBLE","USD","USD value of every asset on NEAR in the exchange's labelled wallets, at DefiLlama's prices.",0,0]]},"fct_protocol_fees_snapshot":{"a":"Capital and DeFi","d":"Fees and revenue per protocol on NEAR, as of each DefiLlama reading.","g":["snapshot_date","measure","protocol_name"],"n":408,"f":"2026-10-28","l":"2026-11-14","s":["defillama"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["measure","VARCHAR","text","fees or revenue.",0,1],["protocol_name","VARCHAR","text","Protocol name.",0,1],["protocol_slug","VARCHAR","id","DefiLlama protocol identifier.",0,0],["category","VARCHAR","text","DefiLlama category.",0,0],["total_24h_usd","DOUBLE","USD","Trailing 24 hours.",0,0],["total_7d_usd","DOUBLE","USD","Trailing 7 days.",0,0],["total_30d_usd","DOUBLE","USD","Trailing 30 days.",0,0],["total_1y_usd","DOUBLE","USD","Trailing year.",0,0],["total_all_time_usd","DOUBLE","USD","All time.",0,0]]},"fct_stablecoin_assets":{"a":"Capital and DeFi","d":"Supply per stablecoin per chain, as of each DefiLlama reading.","g":["snapshot_date","chain_id","symbol","asset_name"],"n":5524,"f":"2026-11-01","l":"2026-11-14","s":["defillama"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["chain_id","VARCHAR","id","Chain identifier from registry/peers.csv.",0,1],["symbol","VARCHAR","text","Stablecoin symbol.",0,1],["asset_name","VARCHAR","text","Stablecoin name.",0,1],["peg_type","VARCHAR","text","What the stablecoin is pegged to.",0,0],["circulating","DOUBLE","pegged units","Circulating supply on the chain, in pegged units.",0,0]]},"fct_yield_pools":{"a":"Capital and DeFi","d":"Yield pools on NEAR, as of each DefiLlama reading. For a lending pool, tvl_usd is the balance that is not lent out, not what was deposited, so it understates the market and cannot be compared with a staking pool's. At the 2026-11-10 pin all ten pools were Rhea's, and most of the value was rNEAR at the staking rate.","g":["snapshot_date","pool_id"],"n":138,"f":"2026-11-01","l":"2026-11-14","s":["defillama"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["pool_id","VARCHAR","id","Pool identifier.",0,1],["project","VARCHAR","text","Protocol running the pool.",0,0],["symbol","VARCHAR","text","Pool tokens.",0,0],["tvl_usd","DOUBLE","USD","Pool TVL as DefiLlama reports it. For a lending pool it is the balance not lent out.",0,0],["apy_pct","DOUBLE","percent","Total APY as DefiLlama reports it. DefiLlama splits it into base and reward; no NEAR pool has had a reward APY, so the base has equalled this on every row and the split stays in silver. A data test says when a reward appears.",0,0]]},"fct_market_daily":{"a":"Market and peers","d":"NEAR price and market cap per UTC day, one column per measure, aligned to the close of the UTC day. price_usd takes the first source with a value: CoinMetrics, Coinbase, DefiLlama, then NearBlocks. price_basis names it, and dq_reconciliation compares the four. market_cap_usd is price times the circulating supply built from the chain in fct_circulating_supply_daily, which is total supply minus what lockups still lock. See docs/CIRCULATING_SUPPLY.md. CoinMetrics' own market cap is compared in dq_reconciliation: its supply is NearBlocks' legacy endpoint through CoinGecko, which froze in August 2025 and has been total supply since 2025-10-25.","g":["date_day"],"n":2307,"f":"2020-07-21","l":"2026-11-13","s":["nearblocks","defillama","coinmetrics","coinbase","rpc","fastnear"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["price_usd","DOUBLE","USD","NEAR close of the UTC day, from the first of CoinMetrics, Coinbase, DefiLlama and NearBlocks that has one; see price_basis. DefiLlama and NearBlocks stamp a day at 00:00 UTC, so their values are moved back a day to the close.",["nearblocks","defillama","coinmetrics","coinbase"],0],["price_basis","VARCHAR","text","Which source price_usd comes from: coinmetrics, coinbase, defillama or nearblocks.",["nearblocks","defillama","coinmetrics","coinbase"],0],["market_cap_usd","DOUBLE","USD","price_usd times fct_circulating_supply_daily.circulating_supply_near: every token not subject to a lockup, including what the NEAR Foundation holds outside lockups. Empty before transfers were enabled on 2020-10-13. Do not read this next to a peer's as the same measure: see market_cap_basis in fct_peer_daily.",0,0],["fully_diluted_value_usd","DOUBLE","USD","price_usd times total supply from fct_supply_daily. Since 2025-10-23 it is what other services publish as NEAR's market cap, and it runs about 0.2% above market_cap_usd.",0,0],["reported_spot_volume_usd","DOUBLE","USD","Spot trading volume across exchanges as reported to CoinMetrics.",["coinmetrics"],0]]},"fct_token_prices":{"a":"Market and peers","d":"Point in time: one USD price per token per read, chosen from 1Click and Rhea on the token's id, never its symbol. 1Click wins where it has a positive price, because 139 of its 152 tokens carry a market feed's id, while Rhea's list is one DEX's pools. A price of 0 or below on either list counts as no price. Tokens with no positive price on either list have no row. native:near takes wrap.near's price, because one redeems for the other one to one. Most of Rhea's list is stale or thin: 4,309 of the 4,609 tokens on all five reads to 2026-11-05 kept one unchanged price while NEAR moved 11%, and one token reads $1.36 trillion. So read price_date and depth_usd before using a Rhea price.","g":["snapshot_date","token_id"],"n":68571,"f":"2026-11-01","l":"2026-11-14","s":["explorer","registry","rhea"],"c":[["snapshot_date","DATE","date","Date the lists were read. On the 11-05 run the two lists were read about four minutes apart.",0,1],["token_id","VARCHAR","token id","Token contract, as fct_wallet_holdings names it, or native:near. For 1Click this is the NEAR contract its asset id names, so bridged assets count too: USDC on Ethereum is eth-0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48.omft.near.",0,1],["price_usd","DOUBLE","USD per token","The price to use: 1Click's if positive, otherwise Rhea's. Per whole token, counted with price_decimals.",["explorer","rhea"],0],["price_source","VARCHAR","text","Which list price_usd came from: oneclick or rhea.",["explorer","rhea"],0],["price_date","DATE","date","When price_usd was last set, as far as its list shows. For 1Click, the date of its priceUpdatedAt. Rhea gives no time, so this is the first read showing this exact price, digit by digit. Earlier than snapshot_date means the price has not changed since then, and it can never read earlier than Rhea's first read, 2026-11-01.",0,1],["price_decimals","INTEGER","integer","The decimals the chosen list uses for this token. A price is per whole token in these decimals, so a holding counted with different decimals cannot use it.",0,0],["price_usd_oneclick","DOUBLE","USD per token","1Click's price. Empty if 1Click does not list the token or lists it at 0, which it did for six tokens on 2026-11-05.",["explorer"],0],["price_usd_rhea","DOUBLE","USD per token","Rhea's price. Empty if Rhea does not list the token or lists it at 0.",["rhea"],0],["price_gap_pct","DOUBLE","percent","How far apart the two lists are, as a percent of the larger price. Empty unless both have a positive price. Above the project's price_disagreement_pct (20), fct_wallet_holdings leaves the value empty.",0,0],["depth_usd","DOUBLE","USD","Assets with a vetted price opposite this token, summed over Rhea's pools at this read. This is the real money behind a pool price: in a constant-product pool, selling any amount cannot take out more than the other side. It does not use Rhea's own tvl field, which reads $1.37B for one pool of two unknown tokens. It leaves out concentrated-liquidity (DCL) pools, which Rhea's pool list does not include, so a token traded only there reads 0.",["rhea"],0],["is_vetted","BOOLEAN","boolean","True if 1Click has a positive price for the token or registry/tokens.csv lists it. Only these prices count toward depth_usd, and only these tokens can be valued beyond their depth.",["explorer","registry"],0]]},"fct_token_price_daily":{"a":"Market and peers","d":"A US-dollar price per UTC day for each main asset of the NEAR Intents pool, so that token balances read from the chain can be valued without NEAR's own dashboard. The set is registry/token_prices.csv: every asset that was at least 1% of the pool on 2026-11-11, the newest day of fct_dune_intents_tvl_asset_daily when the set was chosen, other than wNEAR, whose price is NEAR's in fct_market_daily, and the stablecoins USDC and USDT, counted at one dollar, and for which an independent public price series exists. That is ZEC, BTC, WBTC, ETH, XLM, QTC, TLO and SOL. Each asset has one source for its whole series: CoinMetrics' reference rate where CoinMetrics has a series of the asset's own (ZEC, BTC, ETH, XLM, SOL), and DefiLlama's price otherwise (WBTC, QTC, TLO). No price is worked out from the dashboard, from the 1Click token list or from any figure NEAR publishes about the pool. An asset or a day missing from this table has no price, not a price of zero. QTC is priced from 2026-09-12 and TLO from 2026-09-23, the others from 2024-11-01. The two sources do not take their price at the same moment, so read price_kind. ETH and SOL are also priced in fct_peer_daily, from the same CoinMetrics series; dq_reconciliation holds them against DefiLlama's prices, which come by another route. See docs/SOURCES.md.","g":["date_day","symbol"],"n":4573,"f":"2024-11-01","l":"2026-11-13","s":["defillama","coinmetrics","registry"],"c":[["date_day","DATE","date","UTC calendar day. The price is the one at the end of this day.",0,1],["symbol","VARCHAR","text","Asset symbol, spelled as fct_dune_intents_tvl_asset_daily spells it, so the two join on symbol and day. It is a symbol and not a token id: the pool holds an asset as one or more bridged tokens, and the price is the asset's own.",0,1],["price_usd","DOUBLE","USD per token","Dollars per whole token at the end of the UTC day; price_kind says what kind of price it is and when it is taken. It is the asset's own market price, so valuing the pool's bridged tokens with it assumes each redeems for one of the asset, which nothing here checks. WBTC's is WBTC's own price, not Bitcoin's: over the 741 days to 2026-11-11 it was 0.12% under CoinMetrics' Bitcoin rate at the median and 1.3% under at most.",0,0],["price_source","VARCHAR","text","Where the price comes from: coinmetrics or defillama. An asset keeps one source for its whole series, named in registry/token_prices.csv. Each source's terms are in registry/sources.csv.",["defillama","coinmetrics"],0],["source_asset_id","VARCHAR","id","The source's own id for the series: a CoinMetrics asset id such as zec, or a DefiLlama coin key, which is coingecko:<id> or <chain>:<token contract>.",["defillama","coinmetrics"],0],["price_kind","VARCHAR","label","What kind of price the row holds. reference_rate is CoinMetrics' PriceUSD, its fixed closing price at 00:00 UTC as the day ends, the kind fct_market_daily takes for NEAR. aggregator_price is DefiLlama's price at the stamp nearest that midnight, which may lie up to 2.4 hours either side: at the 2026-11-12 pin every WBTC stamp is within 190 seconds of it and every QTC and TLO stamp within 51 minutes, most of them 7 minutes before. For a coingecko: key DefiLlama passes on CoinGecko's market price; for TLO's contract key its reply does not say how the price is made.",0,0]]},"fct_peer_daily":{"a":"Market and peers","d":"NEAR and peer chains per day. Activity columns use one source and definition for every chain; market_cap_usd does not, so read market_cap_basis before comparing caps. fees_usd and revenue_usd cover the applications on a chain, and gas_fees_usd the chain's own transaction fees. An empty cell means the source has no value for that day. The fees and revenue of the newest days can still change; see is_fee_revenue_provisional.","g":["date_day","chain_id"],"n":15191,"f":"2017-09-27","l":"2026-11-13","s":["defillama","coinmetrics"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["chain_id","VARCHAR","id","Chain identifier from registry/peers.csv.",0,1],["price_usd","DOUBLE","USD","Close of the UTC day: CoinMetrics, else DefiLlama, which is the only source for Sui before 2023-08-17 and for TON before 2022-05-05. TON's CoinMetrics series is the asset `gram` (Toncoin was renamed; the old id `ton` returns nothing), first read on 2026-11-10. NEAR's is fct_market_daily's.",0,0],["price_basis","VARCHAR","text","Which source price_usd comes from: coinmetrics or defillama, or for NEAR whichever fct_market_daily used.",0,0],["market_cap_usd","DOUBLE","USD","Peers: CoinMetrics' estimate, price times the circulating supply the project reports. NEAR: fct_market_daily's, price times total supply minus lockups. TON's is CoinMetrics' asset `gram`, with a cap from 2022-11-03; it is empty in a build pinned before 2026-11-10, when every read still asked for the id `ton`, which returns nothing. These are not one definition, so read market_cap_basis and implied_supply_tokens before comparing.",["coinmetrics"],0],["implied_supply_tokens","DOUBLE","native tokens","market_cap_usd divided by price_usd: the supply behind the cap. On 2026-11-05, as a share of total supply read from each chain: Sui 41% of 10B, Aptos 73%, Solana 93%, Avalanche 93%, Ethereum 100%, NEAR 99.8%.",0,0],["market_cap_basis","VARCHAR","label","What market_cap_usd rests on. A peer's reported figure leaves out whatever its project treats as not circulating, while NEAR's leaves out only lockups, so the NEAR Foundation's liquid holding counts: 305M NEAR, about 26% of supply, at the last figure published (2024-01-11; see registry/near_supply_readings.csv).",0,0],["tvl_usd","DOUBLE","USD","Chain TVL per DefiLlama, and each day's value is the state as that day began, so set it beside the close of the day before. For NEAR it is what sits in lending markets, DEXs and restaking: it leaves out liquid staking, bridges, tokenised assets and exchange wallets (measured on 2026-11-09, when Rhea's lending market and DEX were 98.6% of it). It is counted in dollars and most of what those protocols hold is NEAR or staked NEAR, so it follows NEAR's price; fct_defi_tvl_daily gives NEAR's figure counted in NEAR and marks the days DefiLlama's reading of Rhea Lend halved and came back. DefiLlama can rewrite a chain's history on any night without notice, so no value is ever final and a TVL chart reproduces only at a pin. Its 2026-11-03 read moved 2,079 Ethereum and Solana days back to 2021, by up to 11.4%. Other reads through 2026-11-05 moved at most 8 days by more than 0.01%, and NEAR's series has not moved. See dq_revisions.",["defillama"],0],["fees_usd","DOUBLE","USD","Fees paid to the applications on the chain: DefiLlama's daily total over the protocols it lists there. The chain's own transaction fees are not in it; they are gas_fees_usd. For NEAR most of it is NEAR Intents: $194,787 of $211,521 on 2026-11-08, beside $2,472 of gas, as read on 2026-11-10. DefiLlama also rewrites older days: its 2026-11-04 and 11-05 reads moved 165 and 557 of Solana's days, back to 2025-04-09, by up to 5.6%.",["defillama"],0],["revenue_usd","DOUBLE","USD","Revenue of the applications on the chain per DefiLlama: the part of fees_usd their protocols or token holders keep. What the chain itself keeps or burns from transaction fees is not in it.",["defillama"],0],["gas_fees_usd","DOUBLE","USD","Transaction fees paid to the chain itself, from DefiLlama's own adapter for the chain. Not part of fees_usd. First fetched on 2026-11-10, so it is empty in a build pinned before that date. For NEAR it is within 0.2% of NearBlocks' transaction fees at the day's close in every year, from a different indexer (Allium); dq_reconciliation holds the two together. Each series has its own start: NEAR 2020-10-14, Solana 2021-01-17, Aptos 2022-10-18, Avalanche 2022-11-08, Sui 2024-07-01, TON 2024-09-24; Ethereum's starts before this table does.",["defillama"],0],["dex_volume_usd","DOUBLE","USD","DEX volume on the chain per DefiLlama.",["defillama"],0],["stablecoins_usd","DOUBLE","USD","Stablecoins on the chain per DefiLlama.",["defillama"],0],["reported_spot_volume_usd","DOUBLE","USD","Spot volume in the chain's token that exchanges reported for the day, per CoinMetrics; for NEAR it is fct_market_daily.reported_spot_volume_usd. Reported volume is not audited and can be inflated. TON's starts on 2026-06-29.",["coinmetrics"],0],["is_fee_revenue_provisional","BOOLEAN","boolean","True while this day's fees_usd and revenue_usd can still change, by the rule on fct_intents_daily: until they have been read 4 nights after the day ended, so the newest three days of a nightly build. NEAR's fees are mostly Intents fees and settle with them: they read $33,285 for 2026-10-31 and $146,822 two nights later. Every chain gets the same rule, so filtering on this column cuts them all at the same day. The other chains' first reads also run low, by up to about 6% for fees on Ethereum, Solana and Sui, but they have no fixed settling time, so False does not mean settled for them. A data test holds the number for NEAR only.",0,0]]},"fct_peer_supply_readings":{"a":"Market and peers","d":"Total supply of each chain's token on a day it was read, beside the supply its market cap counted on that day. A peer's market cap counts what its project reports as circulating, so the share differs by chain and no two caps are on one rule. Peers come from registry/peer_supply_readings.csv: each was read once by hand, from the chain or from a provider that indexes it, and is recorded to the million. NEAR's total is the block header's, from fct_supply_daily. TON has no row because its total supply has not been read, so nothing here can place TON on whole supply.","g":["chain_id","reading_date"],"n":6,"f":null,"l":null,"s":["registry","rpc","fastnear","nearblocks","defillama","coinmetrics"],"c":[["chain_id","VARCHAR","id","Chain identifier from registry/peers.csv.",0,1],["reading_date","DATE","date","Day the total supply was read.",0,1],["total_supply_tokens","DOUBLE","native tokens","Total supply of the chain's token on reading_date. Peers' figures are recorded to the million.",0,0],["supply_behind_cap_tokens","DOUBLE","native tokens","fct_peer_daily.implied_supply_tokens on reading_date: the supply the chain's market cap counted that day.",0,0],["share_of_total_counted","DOUBLE","fraction","supply_behind_cap_tokens over total_supply_tokens: the share of total supply that the market cap counts. A market cap over this share is the value of the whole supply at the day's price.",0,0],["read_from","VARCHAR","text","What the total supply was read from: an RPC method of the chain, or a provider's metric.",["rpc"],0],["evidence_level","VARCHAR","label","read_from_chain, or data_provider when a provider indexed it from the chain.",0,0],["note","VARCHAR","text","How the reading was taken and recorded. Empty for NEAR.",0,0]]},"fct_peer_app_fees_snapshot":{"a":"Market and peers","d":"Fees and revenue per application on each of the seven chains, as of each DefiLlama reading, with DefiLlama's category for the application. These are the rows behind fct_peer_daily.fees_usd and revenue_usd: they show what a chain's app fees are made of, such as one application carrying most of them, or yield on tokenised funds and staked tokens booked as fees. The chain's own row (category Chain) is not here; it is fct_peer_chain_fees_snapshot. A reading's 30 days are DefiLlama's trailing 30 days at the moment of the read, not a calendar window. All seven chains have a reading on each night from 2026-11-01; NEAR alone has one of 2026-10-28, with fees only.","g":["snapshot_date","chain_id","protocol_name"],"n":19382,"f":"2026-10-28","l":"2026-11-14","s":["defillama"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["chain_id","VARCHAR","id","Chain identifier from registry/peers.csv.",0,1],["protocol_name","VARCHAR","text","Application name, as DefiLlama lists it.",0,1],["protocol_slug","VARCHAR","id","DefiLlama protocol identifier.",0,0],["category","VARCHAR","text","DefiLlama's category for the application, such as Dexs, Lending, RWA or Liquid Staking. The categories are DefiLlama's; any grouping of them is the reader's own choice.",0,0],["fees_24h_usd","DOUBLE","USD","Fees users paid the application on this chain, trailing 24 hours.",0,0],["fees_7d_usd","DOUBLE","USD","The same, trailing 7 days.",0,0],["fees_30d_usd","DOUBLE","USD","The same, trailing 30 days.",0,0],["fees_1y_usd","DOUBLE","USD","The same, trailing year.",0,0],["revenue_24h_usd","DOUBLE","USD","The part of those fees the application or its token holders keep, trailing 24 hours. Empty when DefiLlama lists fees and no revenue.",0,0],["revenue_7d_usd","DOUBLE","USD","The same, trailing 7 days.",0,0],["revenue_30d_usd","DOUBLE","USD","The same, trailing 30 days.",0,0],["revenue_1y_usd","DOUBLE","USD","The same, trailing year.",0,0],["share_of_chain_fees_30d","DOUBLE","fraction","fees_30d_usd over the sum of fees_30d_usd for the chain in the same reading.",0,0],["is_newest_reading","BOOLEAN","flag","True on the rows of the newest reading in the table.",0,0]]},"fct_peer_chain_fees_snapshot":{"a":"Market and peers","d":"Each chain's own row in DefiLlama's fee and revenue lists (category Chain), as of each reading: the transaction fees users paid the chain, and the part DefiLlama books as the chain's revenue, which is what the chain burns or keeps. It is the only figure the warehouse holds for what reaches a peer's token, and it is thin: one row per chain per night from 2026-11-01. A chain whose 30-day revenue moved more than twofold across the stored readings is flagged as unstable, because a 30-day sum cannot move that far in a few nights unless the source rewrote it. NEAR's row is DefiLlama's own rule, 70% of gas, which stopped being true on 2026-11-04 when all gas began to burn; NEAR's burn read from the chain is fct_supply_daily.burn_near.","g":["snapshot_date","chain_id"],"n":99,"f":"2026-10-28","l":"2026-11-14","s":["defillama","coinmetrics"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["chain_id","VARCHAR","id","Chain identifier from registry/peers.csv.",0,1],["gas_fees_24h_usd","DOUBLE","USD","Transaction fees users paid the chain, trailing 24 hours.",0,0],["gas_fees_7d_usd","DOUBLE","USD","The same, trailing 7 days.",0,0],["gas_fees_30d_usd","DOUBLE","USD","The same, trailing 30 days.",0,0],["gas_fees_1y_usd","DOUBLE","USD","The same, trailing year.",0,0],["chain_revenue_24h_usd","DOUBLE","USD","The part of those fees DefiLlama books as the chain's revenue: what the chain burns or keeps. Trailing 24 hours.",["defillama"],0],["chain_revenue_7d_usd","DOUBLE","USD","The same, trailing 7 days.",0,0],["chain_revenue_30d_usd","DOUBLE","USD","The same, trailing 30 days.",0,0],["chain_revenue_1y_usd","DOUBLE","USD","The same, trailing year.",0,0],["revenue_share_of_gas_30d","DOUBLE","fraction","chain_revenue_30d_usd over gas_fees_30d_usd: the share of gas the chain burns or keeps, by DefiLlama's rule for the chain.",["defillama"],0],["market_cap_day_before_usd","DOUBLE","USD","fct_peer_daily.market_cap_usd on the day before the reading, the newest full day the reading's 30 days cover.",0,0],["multiple_on_chain_revenue","DOUBLE","multiple","market_cap_day_before_usd over chain_revenue_30d_usd times 365/30.",0,0],["revenue_30d_highest_over_lowest","DOUBLE","multiple","The chain's highest chain_revenue_30d_usd across all stored readings over its lowest. The same on every row of a chain.",0,0],["is_unstable","BOOLEAN","flag","True when revenue_30d_highest_over_lowest is above 2: the source rewrote the chain's row between readings, so a figure built on it should be read with and without this chain.",0,0]]},"fct_swap_services_daily":{"a":"Market and peers","d":"NEAR Intents beside six other services that swap a token on one chain for a token on another, per UTC day, so their size can be set side by side. The set is registry/swap_services.csv, chosen on 2026-11-12 by one rule: DefiLlama serves a daily dollar series for the service without a key; the series counts swaps or orders the service itself settles across chains, from its own pools or filled by a solver, relayer or taker on the destination chain; it holds at least 365 days; and its 365 days to 2026-11-11 came to at least a tenth of NEAR Intents' $33.88B. The figures are not one measure, so read figure_kind before setting rows side by side, and do not add rows of different kinds. Aggregators such as LI.FI are left out: they route through these services, NEAR Intents among them, so their volume counts the same swaps again. docs/SOURCES.md lists what else was left out and why.","g":["date_day","service_id"],"n":7045,"f":"2021-04-12","l":"2026-11-13","s":["defillama","registry","nearblocks","revenue"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["service_id","VARCHAR","id","Service identifier from registry/swap_services.csv.",0,1],["service_name","VARCHAR","text","Name of the service.",0,0],["volume_usd","DOUBLE","USD","The service's volume for the day in dollars; figure_kind says which kind of volume it is. NEAR Intents' is fct_intents_daily.volume_usd. The others' are DefiLlama's newest reading of the day, which reads each service's own index or API, so none is an independent count; DefiLlama can restate a day, and dq_revisions lists the days a later read changed. A 0 is the source's own: THORChain reads 0 from 2026-05-16 to 06-21, Mayan from 2026-08-08 to 08-30 and Chainflip on 2026-09-13 and 09-14. Whether the service stood still on those days or the source has a hole is not known, so a sum over them may understate the service. Across has no row for 2026-10-29 and Mayan none for 2026-10-22.",0,0],["figure_kind","VARCHAR","label","What kind of volume the row holds. swap_volume is the value of swaps the service settled: NEAR Intents, and THORChain and Chainflip from DefiLlama's dexs list, where each swap is one token for another. bridge_volume is the value sent into the service on one chain to arrive on another, from DefiLlama's bridges list (its dailyOutgoingVolume), each transfer counted once on the chain it leaves: Relay, Across, Mayan and deBridge. It counts a transfer that delivers the same token on another chain, which is a move and not a swap, so it reads high beside swap_volume. In the 30 days DefiLlama summed at the 2026-11-12 read, 87% of what was sent through Across left Hyperliquid or Arbitrum.",0,0],["what_it_counts","VARCHAR","text","What the service's figure counts, in the words of registry/swap_services.csv, which takes them from the methodology DefiLlama publishes for the series.",["defillama","registry"],0],["volume_basis","VARCHAR","text","Which source the day's figure is from. defillama for every other service. For NEAR Intents it is fct_intents_daily.volume_basis: revenue_page, or defillama on the 29 days the page lacks.",0,0],["is_near_intents","BOOLEAN","boolean","True on NEAR Intents' rows, which are NEAR's own all-route figure as NEAR reports it, confidential routes included. False on the other services' rows.",0,0]]},"fct_etf_nrr_daily":{"a":"Market and peers","d":"The Bitwise NEAR ETF (NRR) per trading day. Flow is the change in shares times that day's NAV, the same maths as the flows SoSoValue reports. flow_basis says how each row's change was reached. A creation does not prove NEAR was bought on the market that day, because shares can be created for cash or for NEAR. Bitwise's terms limit copying its figures: see registry/sources.csv.","g":["date_day"],"n":35,"f":"2026-09-28","l":"2026-11-13","s":["bitwise","sosovalue"],"c":[["date_day","DATE","date","US trading day. The first row, 2026-09-28, is the seed capital, the day before trading began.",0,1],["nav_usd","DOUBLE","USD per share","Net asset value per share, from the chart on Bitwise's page. On a day the chart has not reached, net assets divided by shares.",["bitwise"],0],["market_price_usd","DOUBLE","USD per share","Closing market price per share, from the same chart.",0,0],["premium_discount_pct","DOUBLE","percent","Market price above NAV, or below it if negative.",0,0],["volume_shares","BIGINT","shares","Shares traded that day. Starts with the first saved snapshot, because the page shows only the latest day.",0,0],["shares_outstanding","HUGEINT","shares","Shares at the close. Built from flow_shares through the history file, then taken from Bitwise's page. Empty on a day no snapshot saw.",0,0],["fund_page_shares","BIGINT","shares","The share count on Bitwise's page for that day, where a snapshot saw it. A data test holds shares_outstanding to it.",["bitwise"],0],["net_assets_usd","DOUBLE","USD","Net assets from Bitwise's page where a snapshot saw that day, otherwise shares_outstanding times nav_usd.",["bitwise"],0],["near_in_trust","DOUBLE","NEAR","NEAR the fund holds. Known where a snapshot saw that day, plus two dates in the history file; on 2026-09-28 it is the seed deposit seen on chain.",0,0],["near_per_share","DOUBLE","NEAR per share","near_in_trust divided by shares_outstanding, carried forward from the last day it was known.",0,0],["flow_shares","HUGEINT","shares","Shares created, or redeemed if negative, that day. If a night was missed, the next reading's change covers the days between.",0,0],["flow_baskets","HUGEINT","count","flow_shares in baskets of 10,000 shares, the size set in the prospectus.",0,0],["flow_usd","DOUBLE","USD","flow_shares times nav_usd. Empty for the seed capital, because the reported cumulative figures fit only without it.",0,0],["flow_near","DOUBLE","NEAR","flow_shares times near_per_share: the NEAR those shares stand for.",0,0],["cumulative_flow_usd","DOUBLE","USD","flow_usd added up since launch.",0,0],["flow_basis","VARCHAR","label","How flow_shares was reached. fund_page: the change in Bitwise's share count. reported: a flow reported by SoSoValue, divided by NAV. cumulative_difference: the gap between two reported cumulative figures. chain_settlement: whole baskets settled on chain the next trading day, an estimate. seed_capital: the prospectus's seed baskets.",0,0],["trading_days_covered","BIGINT","count","Trading days this row's change spans. Above 1 means a night without a snapshot came before it.",0,0],["reported_flow_usd","DOUBLE","USD","Daily net flow reported by SoSoValue, read from a news report. A cross-check, except where flow_basis is reported.",["sosovalue"],0],["reported_cumulative_usd","DOUBLE","USD","Cumulative net inflow reported by SoSoValue, read from a news report.",["sosovalue"],0],["reported_net_assets_usd","DOUBLE","USD","Net assets reported by SoSoValue, read from a news report. A data test holds them to shares_outstanding times nav_usd.",["sosovalue"],0],["staked_share","DOUBLE","fraction","Share of the fund's NEAR that is staked, from Bitwise's page.",["bitwise"],0],["net_staking_rate","DOUBLE","fraction per year","Staking reward rate after the fund's staking expenses, from Bitwise's page.",["bitwise"],0],["gross_staking_rate","DOUBLE","fraction per year","Staking reward rate before the fund's staking expenses, from Bitwise's page.",["bitwise"],0],["listed_wallets","UBIGINT","count","Wallets Bitwise's page listed for the fund that night. fct_etf_nrr_chain_daily.wallets_in_pool counts the ones holding NEAR in the staking pool.",["bitwise"],0],["source_url","VARCHAR","url","The report or filing behind this row in the history file.",0,0],["note","VARCHAR","text","How this row in the history file was reached.",0,0]]},"fct_etf_nrr_chain_daily":{"a":"Market and peers","d":"The Bitwise NEAR ETF's (NRR) NEAR as seen on chain, per UTC day: the wallets Bitwise lists, read inside the fund's staking pool at the first block of the next day. NEAR that moves is rounded to baskets of 10,000 shares. The chain settles about one trading day after the trade and nets orders against each other, so use fct_etf_nrr_daily for what traded on a day. NEAR outside the pool is not counted.","g":["date_day"],"n":47,"f":"2026-09-28","l":"2026-11-13","s":["rpc","bitwise"],"c":[["date_day","DATE","date","UTC calendar day the balances close.",0,1],["block_height","BIGINT","block","The block read: the first of the next UTC day.",0,0],["wallets_in_pool","BIGINT","count","Listed wallets holding at least 1 NEAR in the pool.",0,0],["near_in_wallets","DOUBLE","NEAR","NEAR staked or unstaking in the pool across the listed wallets.",0,0],["near_unstaking","DOUBLE","NEAR","The part of near_in_wallets that has been unstaked and not yet withdrawn.",0,0],["rewards_near","DOUBLE","NEAR","Growth in wallets that changed by under 0.1% that day, which is staking rewards.",0,0],["moved_near","DOUBLE","NEAR","All other change in those balances: NEAR deposited, or withdrawn if negative.",0,0],["settled_shares","BIGINT","shares","moved_near as whole baskets of 10,000 shares. Redemptions are negative.",0,0],["left_over_near","DOUBLE","NEAR","The part of moved_near that does not make a whole basket, such as a small rebalance.",0,0],["running_settled_shares","HUGEINT","shares","settled_shares added up since launch, to compare with the fund's share count.",0,0],["moved_value_usd","DOUBLE","USD","moved_near at that day's NEAR price from fct_market_daily. Empty until the price is in.",0,0],["pool_near","DOUBLE","NEAR","All NEAR delegated to the pool, including other delegators.",0,0],["share_of_pool","DOUBLE","fraction","near_in_wallets divided by pool_near.",0,0],["share_of_circulating_supply","DOUBLE","fraction","near_in_wallets divided by circulating supply from fct_circulating_supply_daily.",0,0],["snapshot_date","DATE","date","Snapshot the day was read in. Past blocks do not change, so a later read gives the same balances.",0,1]]},"fct_dev_activity_weekly":{"a":"Developers and governance","d":"Commits and active authors per tracked repository per week, counted from GitHub's commits list on each repository's default branch, by committer date, with one method for every repository. A fixed repository list, not a whole-ecosystem count. GitHub's own weekly statistic is not used: it counts beyond the default branch (1,812 against 1,386 for near/nearcore at the 2026-11-11 pin, 31% more, which dq_reconciliation prints as 23.5% because it divides the gap by the larger figure; near/nearcore keeps release branches; the statistic is lower for some repositories), and it returns a year of zeros for a repository with over 10,000 commits (anza-xyz/agave). Silver keeps it, and dq_reconciliation compares it for near/nearcore.","g":["week_start","repo"],"n":936,"f":"2025-11-09","l":"2026-11-01","s":["github"],"c":[["week_start","DATE","date","Sunday that starts the week, UTC, which is how GitHub cuts its weeks. On the date spine this is dim_date.week_start_sunday; dim_date.week_start is a Monday.",0,1],["repo","VARCHAR","text","GitHub repository as owner/name.",0,1],["ecosystem","VARCHAR","id","Chain the repository belongs to.",0,0],["repo_group","VARCHAR","text","Kind of repository.",0,0],["commits_default_branch","BIGINT","count","Commits that week on the default branch, counted from the commits list by committer date, with the same method for every repository. Empty for a week no read has counted yet.",0,0],["authors_default_branch","BIGINT","count","Distinct authors with a commit on the default branch that week, counted from the commits list; every author, not only the top 100.",0,0]]},"fct_repo_snapshot":{"a":"Developers and governance","d":"Stars, forks and last push per tracked repository, per read.","g":["snapshot_date","repo"],"n":252,"f":"2026-11-01","l":"2026-11-14","s":["github"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["repo","VARCHAR","text","GitHub repository as owner/name.",0,1],["ecosystem","VARCHAR","id","Chain the repository belongs to.",0,0],["repo_group","VARCHAR","text","Kind of repository.",0,0],["stars","BIGINT","count","GitHub stars.",0,0],["forks","BIGINT","count","GitHub forks.",0,0],["open_issues","BIGINT","count","Open issues and pull requests.",0,0],["last_push_date","DATE","date","Date of the last push.",0,1],["created_date","DATE","date","Creation date.",0,1]]},"fct_catalog_projects":{"a":"Developers and governance","d":"NEAR Catalog entries per read, for counting projects by tag over time.","g":["snapshot_date","slug"],"n":4791,"f":"2026-11-01","l":"2026-11-14","s":["nearcatalog"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["slug","VARCHAR","id","Catalog identifier.",0,1],["project_name","VARCHAR","text","Project name.",0,0],["tagline","VARCHAR","text","Catalog tagline.",0,0],["tags_json","JSON","json","Catalog tags, as JSON.",0,0]]},"fct_governance_threads":{"a":"Developers and governance","d":"Engagement on the tracked governance threads, per read. Governance outcomes belong in dim_event.","g":["snapshot_date","topic_id"],"n":56,"f":"2026-11-01","l":"2026-11-14","s":["gov"],"c":[["snapshot_date","DATE","date","Date the source was read.",0,1],["topic_id","BIGINT","id","Forum thread id.",0,1],["title","VARCHAR","text","Short title.",0,0],["created_date","DATE","date","Creation date.",0,1],["last_post_date","DATE","date","Date of the last post.",0,1],["posts","BIGINT","count","Posts in the thread.",0,0],["views","BIGINT","count","Thread views.",0,0],["likes","BIGINT","count","Thread likes.",0,0],["is_closed","BOOLEAN","boolean","Whether the thread is closed.",0,0]]},"fct_governance_proposals":{"a":"Developers and governance","d":"House of Stake proposals read directly from vote.dao, as of the newest snapshot. A status of Voting means the numbers are still moving. Proposals made to try the contract out, and jokes, are kept and marked with is_test: 11 of the 30 at the 2026-11-10 pin.","g":["proposal_id"],"n":30,"f":null,"l":null,"s":["hos"],"c":[["proposal_id","INTEGER","integer","Proposal number in the contract.",0,1],["title","VARCHAR","text","Proposal title.",0,0],["status","VARCHAR","text","Contract status: Created, Rejected, Voting, Timelock, Succeeded or Defeated. Timelock means the vote passed and its waiting period has not ended. The contract records votes and carries nothing out (has_actions), so Succeeded says the vote passed, not that anything changed on the chain.",0,0],["flow","VARCHAR","text","Voting flow, such as Classic.",0,0],["proposer_id","VARCHAR","account id","Account that created the proposal.",0,0],["link","VARCHAR","url","Discussion link given in the proposal.",0,0],["created_date","DATE","date","Date the proposal was created.",0,1],["voting_start_date","DATE","date","Date voting opened. Empty if it never opened.",0,1],["voting_end_date","DATE","date","Date voting closes or closed.",0,1],["for_venear","DOUBLE","veNEAR","veNEAR voting for: the first option in the contract's vote list.",0,0],["against_venear","DOUBLE","veNEAR","veNEAR voting against: the second option.",0,0],["abstain_venear","DOUBLE","veNEAR","veNEAR abstaining: the third option.",0,0],["voters","INTEGER","count","Accounts that voted.",0,0],["votes_venear","DOUBLE","veNEAR","Total veNEAR voted.",0,0],["eligible_venear","DOUBLE","veNEAR","Total veNEAR in the proposal's snapshot.",0,0],["turnout","DOUBLE","fraction","votes_venear divided by eligible_venear.",0,0],["quorum_threshold","DOUBLE","fraction","Share of eligible veNEAR required for quorum.",0,0],["approval_threshold","DOUBLE","fraction","Share of votes required to pass.",0,0],["voters_for","INTEGER","count","Accounts that voted for: the head count of the first option. An account may vote with veNEAR delegated to it, so this counts voting accounts, not holders.",0,0],["voters_against","INTEGER","count","Accounts that voted against.",0,0],["voters_abstain","INTEGER","count","Accounts that abstained.",0,0],["snapshot_accounts","INTEGER","count","Accounts in the snapshot of venear.dao that the vote was taken on: every account that could have voted. Empty if voting never opened.",0,0],["reviewer_id","VARCHAR","account id","Account that approved the proposal for a vote. Empty if it never was.",0,0],["has_actions","BOOLEAN","boolean","True if the proposal carries an action for the contract to run when it passes. False on every proposal so far: a passed vote is a decision on record, which others must carry out.",0,0],["voting_end_utc","TIMESTAMP","timestamp, UTC","The moment voting closes or closed: its start plus the voting period. Empty if voting never opened.",0,1],["timelock_end_utc","TIMESTAMP","timestamp, UTC","The moment the proposal's timelock ends: voting_end_utc plus the timelock the proposal was filed with, so it equals voting_end_utc where there is none. Nothing happens on the chain at this moment (has_actions).",0,1],["venear_growth_per_year","DOUBLE","fraction per year","The rate at which veNEAR grows by itself, as stored with the vote's snapshot: the contract's fraction for each nanosecond times the nanoseconds in 365 days. 0.4998 on every vote so far. Empty if voting never opened.",0,0],["read_on","DATE","date","Date of the reading.",0,1],["is_test","BOOLEAN","boolean","True for a proposal made to try the contract out or as a joke, not a real one: its title says test, or it has a link that is not a forum thread on gov.near.org (https://gov.near.org/t/...). A real proposal either links to its thread or has no link. One test proposal went to a vote and was defeated; a data test fails if a flagged proposal ever passes.",0,0]]},"fct_governance_decisions":{"a":"Developers and governance","d":"Every real vote on vote.dao, one row each, with what it decides. The vote columns are the contract's. What kind of decision it is, what it changes, what it commits and whether it is in force on the chain are read by hand from each proposal's own text and kept in registry/governance_decisions.csv, with the passage each rests on. A vote the registry has not read yet keeps its row with those columns empty.","g":["proposal_id"],"n":11,"f":null,"l":null,"s":["hos","registry"],"c":[["proposal_id","INTEGER","integer","Proposal number in the contract.",0,1],["hsp","VARCHAR","text","The proposal's House of Stake number, such as HSP-029, where its own text or its forum thread gives one. Empty where the text reads TBD or gives none.",["hos"],0],["short_name","VARCHAR","text","A few words that name the vote on a chart or in a sentence, written by hand.",0,0],["kind","VARCHAR","label","What the vote decides. protocol_setting: a value in the protocol's config, which validators must adopt. spending: NEAR or dollars from House of Stake's funds or from emissions. rules: House of Stake's own rules and roles. sensing: a first reading that binds nothing. Empty until the registry has read the proposal.",0,0],["what_it_changes","VARCHAR","text","What the proposal does, in one line, from its own text.",0,0],["title","VARCHAR","text","Proposal title in the contract.",0,0],["status","VARCHAR","text","Contract status as of the newest reading. Succeeded says the vote passed, not that anything changed on the chain: see in_force_date.",0,0],["voting_start_date","DATE","date","Date voting opened.",0,1],["voting_end_date","DATE","date","Date voting closed.",0,1],["voters","INTEGER","count","Accounts that voted.",0,0],["voters_for","INTEGER","count","Accounts that voted for.",0,0],["voters_against","INTEGER","count","Accounts that voted against.",0,0],["voters_abstain","INTEGER","count","Accounts that abstained.",0,0],["snapshot_accounts","INTEGER","count","Accounts in the snapshot of venear.dao that the vote was taken on: every account that could have voted. venear.dao's count of accounts never falls, so this includes accounts that held nothing by then.",["hos"],0],["share_of_accounts_voting","DOUBLE","fraction","voters divided by snapshot_accounts. An account may vote with veNEAR delegated to it, so this is the share of accounts that voted, not of holders.",0,0],["support","DOUBLE","fraction","veNEAR for divided by veNEAR for plus against. Abstentions are left out; they count toward turnout only.",0,0],["approval_threshold","DOUBLE","fraction","The support the vote needed to pass.",0,0],["for_venear","DOUBLE","veNEAR","veNEAR voting for.",0,0],["against_venear","DOUBLE","veNEAR","veNEAR voting against.",0,0],["abstain_venear","DOUBLE","veNEAR","veNEAR abstaining.",0,0],["eligible_venear","DOUBLE","veNEAR","All veNEAR in the vote's snapshot.",0,0],["turnout","DOUBLE","fraction","veNEAR that voted, for, against or abstaining, divided by eligible_venear.",0,0],["quorum_threshold","DOUBLE","fraction","The turnout the vote needed to count.",0,0],["timelock_end_utc","TIMESTAMP","timestamp, UTC","The moment the proposal's timelock ends, which is the moment voting closed where there is none. Nothing happens on the chain at this moment.",0,1],["near_committed","DOUBLE","NEAR","NEAR the proposal's text commits, where it names an amount. No payment is traced in the warehouse.",0,0],["usd_committed","DOUBLE","USD","Dollars the proposal's text commits, where it names an amount.",0,0],["ramp_months","INTEGER","months","For a protocol setting that changes in steps: the months the change takes from its first step to its last, by the proposal's text.",0,0],["grace_days","INTEGER","days","Days the proposal's text sets between its ratification and its first step.",0,0],["in_force_date","DATE","date","The day the chain showed the change, for a protocol setting. Empty while the protocol config has not changed, and for votes that change nothing in the config.",0,1],["in_force_protocol_version","INTEGER","integer","The protocol version that carried the change (registry/protocol_upgrades.csv).",["registry"],0],["evidence","VARCHAR","text","The passages of the proposal's text, and the other records, that the hand-kept columns rest on.",0,0],["source_url","VARCHAR","url","The proposal's forum thread, where it gives one.",0,0]]},"fct_venear_snapshot":{"a":"Developers and governance","d":"House of Stake participation per day, read directly from venear.dao, at the first block of each UTC day from the archival node. The table starts on the first day the contract existed. veNEAR is voting power, not NEAR locked: it grows by itself at a fixed yearly rate on the NEAR locked (fct_governance_proposals.venear_growth_per_year), so the total rises on days when nobody locks anything.","g":["snapshot_date"],"n":400,"f":"2025-10-11","l":"2026-11-14","s":["rpc"],"c":[["snapshot_date","DATE","date","The UTC date of the block the values were read at. With read_from = archival that is the day's first block, so the row shows the state as the day began, which is the close of the day before. With read_from = nightly it is the tip when that date's snapshot ran, some hours into the day.",0,1],["total_venear","DOUBLE","veNEAR","veNEAR outstanding: voting power, which includes the growth credited since each lock. It is not an amount of NEAR, so over NEAR's supply it is an upper bound on the share locked.",0,0],["accounts","BIGINT","count","Accounts registered with venear.dao. The count has never fallen, on days when veNEAR left included, so it counts accounts ever registered and not accounts holding veNEAR today.",0,0],["read_from","VARCHAR","label","archival: replayed from the archival node at the first block of the UTC day. nightly: read at the tip when the snapshot of that date ran, used only for a date the replay has not read. All of a contract's figures on a date come from the same read.",0,0]]},"fct_thesis_scorecard":{"a":"Thesis models","d":"Every claim in dim_claim measured against the warehouse: the value, the bar, and whether the claim holds. holds means the claim as written is true of the data, so a bear claim that holds counts against the thesis and a bull claim that fails does too. A claim the data cannot settle stays in the table as not_testable. The measurement behind each row is a select named by its claim_id in warehouse/models/gold/thesis/fct_thesis_scorecard.sql, and dim_claim.test says in words what it reads.","g":["claim_id"],"n":23,"f":null,"l":null,"s":["bitwise","coinbase","coinmetrics","defillama","dune","explorer","fastnear","nearblocks","neardata","registry","revenue","rpc","sosovalue"],"c":[["claim_id","VARCHAR","id","Claim from dim_claim.",0,1],["side","VARCHAR","label","bull or bear, from dim_claim.",0,0],["claim","VARCHAR","text","The claim in one sentence, from dim_claim.",0,0],["value","DOUBLE","see dim_claim.unit","The measured value, in dim_claim.unit. Empty for a claim that cannot be tested.",0,0],["comparison","VARCHAR","label","How the value is held to the threshold, from dim_claim.",0,0],["threshold","DOUBLE","see dim_claim.unit","The bar, from dim_claim.",0,0],["status","VARCHAR","label","holds if the value meets the bar, fails if it does not, not_testable if the claim has no test. A fourth value, not_measured, would mean a test returned nothing, and a data test fails the build if it appears.",0,0],["as_of_date","DATE","date","The newest day, or the last day of the month, the value rests on.",0,1]],"v":1},"fct_thesis_scorecard_daily":{"a":"Thesis models","d":"The scorecard on every day since 2025-01-01: each tested claim in dim_claim measured as fct_thesis_scorecard measures it, with every input cut at that day. It answers what the scorecard would have said with the data up to a day, from the warehouse as it stands now; it is not a record of what was read on the day, because sources revise recent days. On its newest day it equals fct_thesis_scorecard, and a data test fails the build if it does not. A claim reads not_yet_testable until the window its test needs is whole: six complete months for a test of three months against three, three for a three-month test, a year of readings for a yearly test, and var thesis_lead_test_min_weeks weekly changes for the lead test. The claims and their bars were set in November 2026 with these series in view, so the table shows how today's tests read on earlier data and is not evidence of its own. Claims that cannot be tested are left out. One row per day and tested claim.","g":["date_day","claim_id"],"n":12977,"f":"2025-01-01","l":"2026-11-14","s":["bitwise","coinbase","coinmetrics","defillama","dune","explorer","fastnear","nearblocks","neardata","registry","revenue","rpc","sosovalue"],"c":[["date_day","DATE","date","The day the data is cut at: no input later than this day is read.",0,1],["claim_id","VARCHAR","id","Claim from dim_claim. Only claims with a test.",0,1],["side","VARCHAR","label","bull or bear, from dim_claim.",0,0],["value","DOUBLE","see dim_claim.unit","The measured value on the data up to date_day, in dim_claim.unit, rounded to ten decimals as the scorecard rounds. Empty while the claim is not_yet_testable, and on the days a_doubling_of_volume_reaches_deflation_after_the_cut has no multiple because no fee reached the revenue wallets in its 30 days.",0,0],["status","VARCHAR","label","holds if the value meets the claim's bar, fails if it does not, not_yet_testable while the window the test needs is not whole or its data has not begun. The doubling claim fails without a value when no fee reached the wallets, since no multiple of volume would then do.",0,0],["stands","VARCHAR","label","What the result does to the long case: for when a bull claim holds or a bear claim fails, against when a bull claim fails or a bear claim holds. Empty while the claim is not_yet_testable.",0,0],["as_of_date","DATE","date","The newest day, or the last day of the month, the value rests on, as of date_day.",0,1]],"v":1},"dim_claim":{"a":"Thesis models","d":"The claims a long-term case for NEAR rests on, and the claims made against it, each with the measurement that would settle it and the bar it is held to. fct_thesis_scorecard evaluates them. The set was cut from 29 claims to 20 on 2026-11-11 by four rules: a claim sits on the chain the thesis argues (Intents grows, NEAR keeps more of its fees, the revenue reaches the token, supply growth slows, and the price paid) or names a risk to it; no measurement is scored twice; a claim must be able to hold and able to fail; and a claim about Intents reads three complete months together, so that one month does not decide it. On 2026-11-12 one claim was added, the working hypothesis in the track's sample prompt (that Intents volume leads network usage), and the usage claim was pointed at distinct signers in place of transactions; two more came from the review of the Capital page, one for the case (dollars held in NEAR Intents are rising) and one against it (less NEAR sits in liquid staking than a year ago). The same day the security claim was pointed at the ten largest pools' share of the stake in place of the number of validator pools, because the pools that left in 60 days held under 1% of the stake. Nineteen claims are tested and four cannot be. The thresholds were written between 2026-11-10 and 2026-11-12 with the readings of those days in view, so they are round bars for what each claim's wording means, not predictions; why_this_threshold gives the reason for each. Where a claim was made in public, source_url points to it.","g":["claim_id"],"n":23,"f":null,"l":null,"s":["registry"],"c":[["claim_id","VARCHAR","id","Short name of the claim.",0,1],["side","VARCHAR","label","bull if the claim supports a long-term case for NEAR, bear if it counts against one.",0,0],["pillar","VARCHAR","label","The part of the thesis the claim belongs to.",0,0],["claim","VARCHAR","text","The claim in one sentence.",0,0],["test","VARCHAR","text","What is measured and from which gold table, or why the claim cannot be tested.",0,0],["comparison","VARCHAR","label","How the measured value is held to the threshold: >= or <=. Empty for a claim that cannot be tested.",0,0],["threshold","DOUBLE","see unit","The bar. The claim holds when the value meets it.",0,0],["unit","VARCHAR","text","Unit of the value and the threshold.",0,0],["why_this_threshold","VARCHAR","text","The reason for the bar.",0,0],["source_url","VARCHAR","url","Where the claim was made in public, where one was found.",0,0]]},"fct_net_dilution_daily":{"a":"Thesis models","d":"How much a holder is diluted, how a staker is paid and how much of issuance comes back, over the 30 days ending on each day. Issuance arrives per epoch and revenue is swept in lumps, so one day says little: every figure is a 30-day sum or a rate built from one, and rates are annualized by 365/30. The NEAR received by the revenue wallets is held there, not burned.","g":["date_day"],"n":2278,"f":"2020-08-19","l":"2026-11-13","s":["rpc","fastnear","nearblocks","defillama","coinmetrics","coinbase"],"c":[["date_day","DATE","date","Last day of the 30-day window, a UTC calendar day.",0,1],["minted_30d_near","DOUBLE","NEAR","NEAR issued over the window: the sum of fct_supply_daily.minted_near.",0,0],["burn_30d_near","DOUBLE","NEAR","NEAR burned as gas over the window: the sum of fct_supply_daily.burn_near, which is a lower bound on days before protocol version 87; see is_burn_lower_bound.",0,0],["revenue_inflow_30d_near","DOUBLE","NEAR","NEAR and wNEAR received by the three revenue wallets over the window, from fct_revenue_inflows_daily. Since the fee switch of 2026-02-23 this is NEAR bought with Intents fees. The wallets hold it; it is not burned, so it leaves the market but not the supply.",0,0],["net_issuance_30d_near","DOUBLE","NEAR","minted_30d_near minus burn_30d_near minus revenue_inflow_30d_near: what the window added to the NEAR outside the revenue wallets.",0,0],["offset_share","DOUBLE","fraction","burn_30d_near plus revenue_inflow_30d_near, over minted_30d_near: the share of issuance that came back. Empty before issuance began on 2020-10-20.",0,0],["gross_inflation_rate","DOUBLE","fraction per year","minted_30d_near times 365/30, over the window's mean total supply.",0,0],["net_inflation_rate","DOUBLE","fraction per year","net_issuance_30d_near times 365/30, over the window's mean total supply. Above zero means supply outside the revenue wallets is still growing.",0,0],["nominal_staking_yield_rate","DOUBLE","fraction per year","Issuance paid to validators and their delegators over the window (minted less the treasury's share), times 365/30, over the window's mean stake. Before pool commission, which the warehouse does not hold. Empty where fewer than five days of the window have a validator reading; the readings are sampled epochs, sparse before 2025-10.",0,0],["real_staking_yield_rate","DOUBLE","fraction per year","nominal_staking_yield_rate minus gross_inflation_rate: what staking pays beyond the dilution every holder bears.",0,0],["staked_share","DOUBLE","fraction","The share of total supply that is staked, as a 30-day mean: the window's mean stake over its mean total supply, from the same sampled epochs as the yield. It is the same ratio as fct_validator_summary.staking_ratio, which gives it for one epoch.",0,0],["minted_30d_usd","DOUBLE","USD","The window's issuance at each day's closing price. Empty where a day of the window has no price.",0,0],["revenue_inflow_30d_usd","DOUBLE","USD","The window's revenue inflows in USD: the sum of fct_revenue_inflows_daily.received_usd.",0,0],["is_burn_lower_bound","BOOLEAN","boolean","True while the window holds a day before protocol version 87 (2026-11-04), when part of each gas fee was rebated to contracts and burn_near is a lower bound. From 2026-12-04 every window is exact.",0,0]]},"fct_deflation_scenarios":{"a":"Thesis models","d":"The Intents volume at which NEAR's supply would stop growing, under today's issuance and under the end state of HSP-029, at several shares of fees kept. All inputs are measured over the 30 days ending on as_of_date. Revenue is in dollars and issuance in NEAR, so break-even volume rises in step with price_usd and falls in step with fee_rate; a reader can rescale a row to another price or fee rate. The fee rate and the capture rate are held fixed, though both depend on which flows grow.","g":["scenario_id","capture_case"],"n":8,"f":null,"l":null,"s":["registry","rpc","fastnear","nearblocks","defillama","coinmetrics","coinbase","revenue"],"c":[["as_of_date","DATE","date","The newest day whose Intents fees are settled; every input is the 30 days ending here, and price_usd is this day's close.",0,1],["scenario_id","VARCHAR","id","Issuance scenario from registry/issuance_scenarios.csv: current is what the chain minted over the window; hsp029_end_state is 1.6% of supply a year, which has passed its vote but is not in force.",0,1],["capture_case","VARCHAR","label","Which capture rate the row assumes: measured, or at_50_pct, at_70_pct, at_100_pct.",0,1],["issuance_near_per_day","DOUBLE","NEAR","NEAR issued per day in the scenario.",0,0],["burn_near_per_day","DOUBLE","NEAR","NEAR burned as gas per day over the window, held fixed across scenarios.",0,0],["price_usd","DOUBLE","USD per token","NEAR's close on as_of_date, from fct_market_daily.",0,0],["fee_rate","DOUBLE","fraction","Intents fees over Intents volume across the window.",0,0],["capture_rate","DOUBLE","fraction","Share of Intents fees that reaches the revenue wallets: the window's revenue over fees for the measured case, else the case's rate.",0,0],["volume_usd_per_day","DOUBLE","USD","Mean daily all-route Intents volume over the window.",0,0],["breakeven_volume_usd_per_day","DOUBLE","USD","Daily Intents volume at which the NEAR bought with captured fees equals issuance less burn: (issuance_near_per_day - burn_near_per_day) x price_usd / (fee_rate x capture_rate).",0,0],["breakeven_volume_multiple","DOUBLE","multiple","breakeven_volume_usd_per_day over volume_usd_per_day: how many times today's volume it would take.",0,0],["net_inflation_rate_at_current_volume","DOUBLE","fraction per year","What net inflation would be in the scenario at today's volume: issuance less burn less the NEAR that volume_usd_per_day x fee_rate x capture_rate buys, times 365, over mean supply.",0,0]]},"fct_intents_unit_economics_monthly":{"a":"Thesis models","d":"NEAR's Intents revenue per month, split into what makes it: volume, the fee rate charged on it, and the share of fees NEAR keeps. revenue_usd = volume_usd x fee_rate x capture_rate, so a month's change splits exactly into three log effects. Volume and fees are NEAR's own all-route series and revenue is what reached the wallets, which are swept in lumps, so a month is the shortest span on which capture means anything. Days whose fees can still change are left out, so the newest month is short.","g":["month_start"],"n":24,"f":"2024-12-01","l":"2026-11-01","s":["nearblocks","defillama","revenue"],"c":[["month_start","DATE","date","First day of the month.",0,1],["days_counted","BIGINT","days","Days of the month with settled figures.",0,0],["is_month_complete","BOOLEAN","boolean","True when every day of the month is counted. The newest month is not.",0,0],["volume_usd","DOUBLE","USD","All-route Intents volume over the counted days.",0,0],["fees_usd","DOUBLE","USD","Intents fees over the counted days. Fee data begins in May 2025.",0,0],["revenue_usd","DOUBLE","USD","Revenue that reached NEAR's wallets over the counted days.",0,0],["fee_rate","DOUBLE","fraction","fees_usd over volume_usd, on the days that have fees.",0,0],["capture_rate","DOUBLE","fraction","revenue_usd over fees_usd: the share of fees NEAR keeps. The rest stays with distribution partners, solvers and front ends.",0,0],["net_take_rate","DOUBLE","fraction","revenue_usd over volume_usd: what NEAR keeps per dollar swapped.",0,0],["confidential_volume_share","DOUBLE","fraction","One minus public volume over all-route volume, on the days that have a public figure, with public volume capped at all-route volume day by day because the two come from different sources. Empty before public volume is held.",0,0],["revenue_log_change","DOUBLE","log points","Change in the natural log of revenue per day from the month before. It equals the sum of the three effects. Empty unless both months are complete, have fees on every day and at least $1,000 of revenue; the wallets' first months held test transfers.",0,0],["volume_log_effect","DOUBLE","log points","The part of revenue_log_change from volume per day.",0,0],["fee_rate_log_effect","DOUBLE","log points","The part of revenue_log_change from the fee rate.",0,0],["capture_log_effect","DOUBLE","log points","The part of revenue_log_change from the capture rate.",0,0]]},"fct_intents_channel_economics_monthly":{"a":"Thesis models","d":"What each 1Click distribution channel brought in per month: finished volume, the app fees charged on it, and the fee rate that implies. It shows who prices NEAR's fee base. 1Click is one part of NEAR Intents (27% to 45% of volume in 2026) and only its unbroken daily run is used. App fees are what a channel adds for itself or passes on; they are not NEAR's revenue.","g":["month_start","referral"],"n":2397,"f":"2025-05-01","l":"2026-11-01","s":["explorer"],"c":[["month_start","DATE","date","First day of the month.",0,1],["referral","VARCHAR","text","The channel, as the integrator names itself to 1Click. (none) is every swap sent without a name, a bucket and not one channel.",0,1],["is_month_complete","BOOLEAN","boolean","True when the daily run covers every day of the month.",0,0],["finished_swaps","HUGEINT","count","Swaps that finished.",0,0],["refunded_swaps","HUGEINT","count","Swaps that were refunded.",0,0],["refunded_share","DOUBLE","fraction","refunded_swaps over finished plus refunded swaps.",0,0],["volume_usd","DOUBLE","USD","USD paid in on finished swaps.",0,0],["app_fee_usd","DOUBLE","USD","App fees on finished swaps.",0,0],["app_fee_rate","DOUBLE","fraction","app_fee_usd over volume_usd. 0.0082 is 82 basis points.",0,0],["share_of_volume","DOUBLE","fraction","The channel's share of the month's finished 1Click volume.",0,0],["share_of_fees","DOUBLE","fraction","The channel's share of the month's 1Click app fees.",0,0],["fee_rank","BIGINT","integer","Rank within the month by app fees, 1 the largest.",0,0]]},"fct_intents_concentration_monthly":{"a":"Thesis models","d":"How concentrated NEAR Intents is, per month, along four cuts: 1Click channels by volume and by fees, and all-route volume by blockchain and by asset. The blockchain and asset cuts read NEAR's dashboard on Dune, which splits every route, confidential ones included, and stop at its last reading. covered_share_of_volume says how much of all-route volume a cut can see: 1Click is a minority of volume, and the dashboard's cuts see all of it.","g":["month_start","dimension"],"n":86,"f":"2024-12-01","l":"2026-11-01","s":["dune","explorer","nearblocks","defillama","revenue"],"c":[["month_start","DATE","date","First day of the month.",0,1],["dimension","VARCHAR","label","The cut: channel_volume and channel_fees (1Click, finished swaps of the daily run), chain_volume and asset_volume (all routes, per NEAR's dashboard on Dune).",0,1],["is_month_complete","BOOLEAN","boolean","True when the cut's source has every day of the month.",0,0],["members","BIGINT","count","Channels, blockchains or assets with a positive amount in the month. For channels, (none) counts as one.",0,0],["total_usd","DOUBLE","USD","The month's amount across all members: volume, or app fees for channel_fees.",0,0],["hhi","DOUBLE","index 0 to 1","Herfindahl index: the sum of squared shares. 1 is a single member; 1 over the number of members is an even split.",0,0],["top_1_share","DOUBLE","fraction","Share of the largest member.",0,0],["top_3_share","DOUBLE","fraction","Share of the three largest members.",0,0],["top_10_share","DOUBLE","fraction","Share of the ten largest members.",0,0],["top_member","VARCHAR","text","The largest member.",0,0],["covered_share_of_volume","DOUBLE","fraction","total_usd over the month's all-route Intents volume, for the three volume cuts: how much of Intents the cut sees. Empty for channel_fees.",0,0]]},"fct_valuation_multiples_daily":{"a":"Thesis models","d":"Market cap over a year of income, for NEAR and six peers, on five ideas of income, one row each because the choice of basis moves NEAR's rank more than anything else. gas_fees is what users paid the chain itself; app_fees what they paid applications on it; all_fees the two together; app_revenue the part of app fees the applications or their tokens keep, which does not go to the chain's own token; holder_revenue, for NEAR only, is gas burned plus NEAR received by the revenue wallets. A year of income is the trailing 30 days times 365/30. Market caps are not on one definition across chains: read fct_peer_daily.market_cap_basis before comparing.","g":["date_day","chain_id","basis"],"n":43804,"f":"2020-01-01","l":"2026-11-13","s":["defillama","coinmetrics","rpc","fastnear","nearblocks","coinbase"],"c":[["date_day","DATE","date","Last day of the 30-day window, a UTC calendar day.",0,1],["chain_id","VARCHAR","id","Chain identifier from registry/peers.csv.",0,1],["basis","VARCHAR","label","Which income the multiple uses: gas_fees, app_fees, all_fees, app_revenue or holder_revenue.",0,1],["basis_30d_usd","DOUBLE","USD","The basis summed over the 30 days ending on date_day. A window that lacks one day is scaled up by 30/29, and days_with_value says so; a window that lacks more, or reaches back before the series began, has no row.",0,0],["multiple","DOUBLE","multiple","fct_peer_daily.market_cap_usd on date_day over basis_30d_usd times 365/30.",0,0],["is_provisional","BOOLEAN","boolean","fct_peer_daily.is_fee_revenue_provisional for the day: true on the newest three days, whose fees and revenue can still change.",0,0],["days_with_value","BIGINT","days","Days of the 30 that hold a value: 30, or 29 when basis_30d_usd was scaled up from a window with one empty day.",0,0],["basis_90d_usd","DOUBLE","USD","The basis summed over the 90 days ending on date_day. A window that lacks up to three days is scaled up to 90; one that lacks more, or reaches back before the series began, is empty.",0,0],["multiple_90d","DOUBLE","multiple","fct_peer_daily.market_cap_usd on date_day over basis_90d_usd times 365/90.",0,0],["days_with_value_90d","BIGINT","days","Days of the 90 that hold a value.",0,0],["basis_365d_usd","DOUBLE","USD","The basis summed over the 365 days ending on date_day. A window that lacks up to twelve days is scaled up to 365; one that lacks more, or reaches back before the series began, is empty.",0,0],["multiple_365d","DOUBLE","multiple","fct_peer_daily.market_cap_usd on date_day over basis_365d_usd: the market cap over the last 365 days of income as they were, with no 30-day figure stretched to a year.",0,0],["days_with_value_365d","BIGINT","days","Days of the 365 that hold a value.",0,0]]},"fct_usage_quality_daily":{"a":"Thesis models","d":"Transactions with the known batch streams taken out, so usage can be read across the break of 2026-04-02 (docs/USAGE_BREAK_2026-04-02.md), and with the Sweat relayer taken out as well, since Sweat Wallet ends on 2026-12-30. The streams are counted from NearBlocks' per-account statistics, which reach back 365 active days from their first read, so the table starts where the Kai-Ching accounts' statistics do and the Sweat columns start later. A transaction that touches two of the stream accounts is counted in both, so the series without them is a floor. From 2025-11-01 the day is also split into five layers that add up to fct_chain_daily.txns: batch_stream_txns, hot_game_txns, sweat_relayer_txns, intents_txns and other_txns. The split assumes that no transaction touches two of those accounts, and a data test keeps other_txns from going below zero.","g":["date_day"],"n":583,"f":"2025-04-10","l":"2026-11-13","s":["nearblocks","neardata","defillama","coinmetrics","coinbase","rpc","fastnear"],"c":[["date_day","DATE","date","UTC calendar day.",0,1],["batch_stream_txns","HUGEINT","count","Transactions involving hotwallet.kaiching, users.kaiching or sweat-migration.near: the fixed daily batch that stopped on 2026-04-01 and the three-week key migration that ended on 2026-04-02.",0,0],["sweat_relayer_txns","HUGEINT","count","Transactions involving sweat-relayer.near. Empty before 2025-11-01, where its statistics begin.",0,0],["txns_ex_batch_streams","HUGEINT","count","fct_chain_daily.txns minus batch_stream_txns.",0,0],["txns_ex_batch_streams_and_sweat","HUGEINT","count","txns_ex_batch_streams minus sweat_relayer_txns: roughly what remains once Sweat Wallet has ended.",0,0],["hot_game_txns","HUGEINT","count","Transactions involving game.hot.tg, the contract of HOT's game. HOT is named from the account id only. Empty before 2025-11-01, where its statistics begin. Its relayers relay.tg (to 2026-04-13) and 0here.tg (from 2026-09-28) are not added, because their transactions already touch the game.",0,0],["intents_txns","HUGEINT","count","Transactions involving intents.near, the NEAR Intents contract. Empty before 2025-11-01, where its statistics begin. A swap can take more than one of these, and a swap that settles confidentially may take none that names the user.",0,0],["other_txns","HUGEINT","count","fct_chain_daily.txns minus batch_stream_txns, sweat_relayer_txns, hot_game_txns and intents_txns: everything outside the two batch streams and the three known programs. Empty before 2025-11-01.",0,0],["sweat_share_of_txns_ex_batch_streams","DOUBLE","fraction","sweat_relayer_txns over txns_ex_batch_streams.",0,0],["txn_fee_usd","DOUBLE","USD","fct_chain_daily.txn_fee_near at the day's closing price.",0,0],["txn_fee_per_txn_near","DOUBLE","NEAR","fct_chain_daily.txn_fee_near over all of the day's transactions, batch streams included.",0,0],["sweat_gas_burn_share","DOUBLE","fraction","Share of the gas burnt in the day's sampled blocks whose receiver is labelled Sweat Economy, from fct_receiver_sample_daily. An estimate from a sample: 24 blocks a day before 2026-10-30 and 96 since, so read it over a week or more. Empty before the sample begins.",0,0],["is_before_usage_break","BOOLEAN","boolean","True before 2026-04-03. Raw transaction and account counts are not comparable across that date; the columns here without the streams are.",0,0]]},"fct_usage_lead_correlations":{"a":"Thesis models","d":"The working hypothesis in the track's sample prompt, tested: is cross-chain volume through NEAR Intents a better leading indicator of network usage than the token price? Each row is one Pearson correlation between week-on-week log changes, a leader against a usage measure, with the leader in the same week or one, two or four weeks ahead. Weeks are blocks of seven days counted from 2026-04-13 and usage changes start with the second block, so none crosses the break of 2026-04-02 or the stop of relay.tg on 2026-04-13; only full blocks are read. With about 30 weeks only a link above 0.37 can be told from chance, so the table can rule out a strong lead and not a weak one. Same-week figures move with the weekday a week starts on, which is why week_shift_days keeps all seven cuts.","g":["week_shift_days","leader","usage_measure","lead_weeks"],"n":224,"f":null,"l":null,"s":["nearblocks","defillama","revenue","coinmetrics","coinbase","rpc","fastnear","neardata"],"c":[["week_shift_days","INTEGER","days","0 for weeks cut on Mondays, the reading fct_thesis_scorecard and the site use. 1 to 6 cut the same days one to six days later, as a check on how far a figure moves with the weekday alone.",0,1],["leader","VARCHAR","label","What is tested as leading: intents_volume (fct_intents_daily.volume_usd, all routes, summed over the week) or near_price (fct_market_daily.price_usd, the week's mean of daily closes).",0,1],["usage_measure","VARCHAR","label","The usage series, as the week's mean per day: transactions (txns_ex_batch_streams_and_sweat), other_transactions (other_txns, which also leaves out HOT's game and Intents' own transactions), signers (fct_chain_daily.distinct_signers) or gas_paid (fct_chain_daily.gas_fee_near).",0,1],["lead_weeks","INTEGER","weeks","How many weeks the leader's change comes before the usage change: 0 for the same week, then 1, 2 and 4.",0,1],["correlation","DOUBLE","correlation","Pearson correlation of the two series of week-on-week log changes. From -1 to +1; not a percentage.",0,0],["weeks","BIGINT","count","Weekly changes the correlation rests on.",0,0],["chance_bound","DOUBLE","correlation","The largest correlation, either way, that chance alone gives 19 times in 20 between two unrelated series of that many weeks: the two-sided 5% bound for Pearson's r, with 1.96 + 2.4/df standing in for Student's t.",0,0],["first_week","DATE","date","First day of the first week whose usage change is read.",0,1],["last_week","DATE","date","First day of the last full week read.",0,1]]},"fct_etf_absorption_daily":{"a":"Thesis models","d":"The Bitwise NEAR ETF's flows against what the chain issued and what the revenue wallets took in, from the fund's first trading day, one row per trading day. The seed baskets of 2026-09-28 are left out of the flow, and the seed day has no row. A creation is NEAR delivered to the trust, which need not have been bought on the market that day, and redemptions reverse it. Only this one fund is tracked.","g":["date_day"],"n":34,"f":"2026-09-29","l":"2026-11-13","s":["bitwise","sosovalue","rpc","fastnear","nearblocks","defillama","coinmetrics","coinbase"],"c":[["date_day","DATE","date","Trading day.",0,1],["cumulative_flow_near","DOUBLE","NEAR","Running sum of fct_etf_nrr_daily.flow_near since the fund's first trading day, without the seed baskets.",0,0],["cumulative_minted_near","DOUBLE","NEAR","NEAR the chain issued from the fund's first trading day through this day, every calendar day counted.",0,0],["cumulative_revenue_inflow_near","DOUBLE","NEAR","NEAR the revenue wallets received over the same days.",0,0],["cumulative_flow_to_issuance_ratio","DOUBLE","multiple","cumulative_flow_near over cumulative_minted_near: how many times the chain's issuance the fund has taken in since it opened.",0,0],["flow_to_issuance_ratio","DOUBLE","multiple","The day's fund flow in NEAR over the NEAR issued that day. Issuance arrives per epoch, so read single days loosely.",0,0],["flow_share_of_spot_volume","DOUBLE","fraction","The day's fund flow in USD over NEAR's reported spot volume that day; negative on a day of net redemptions.",0,0],["flow_30d_near","DOUBLE","NEAR","Net NEAR the fund took in over the 30 days ending this day: fct_etf_nrr_daily.flow_near on the trading days inside them. Empty until the fund has traded for 30 days.",0,0],["minted_30d_near","DOUBLE","NEAR","NEAR the chain issued over the same 30 days, every calendar day counted.",0,0],["flow_to_issuance_30d_ratio","DOUBLE","multiple","flow_30d_near over minted_30d_near: how many times the chain's issuance the fund took in over the last 30 days. Negative when it handed back more NEAR than it took in.",0,0]]},"dq_reconciliation":{"a":"Data quality","d":"Every place two sources should agree, side by side. Gold keeps one column per measure, so the sources a gold table chooses between are compared here, read from silver. A gap beyond tolerance must have a written explanation, or make verify fails.","g":["check_id","subject"],"n":125,"f":null,"l":null,"s":["bigquery","bitwise","coinbase","coinmetrics","defillama","dune","explorer","fastnear","github","nearblocks","registry","revenue","rhea","rpc","sosovalue"],"c":[["check_id","VARCHAR","id","Name of the check.",0,1],["metric","VARCHAR","text","What is being measured.",0,0],["subject","VARCHAR","text","What the check is about, when it runs per account.",0,1],["source_a","VARCHAR","text","First source.",0,0],["value_a","DOUBLE","see metric","Value from the first source.",0,0],["source_b","VARCHAR","text","Second source.",0,0],["value_b","DOUBLE","see metric","Value from the second source.",0,0],["diff_pct","DOUBLE","percent","Absolute gap as a percentage of the larger value.",0,0],["tolerance_pct","DECIMAL(4,2)","percent","Largest gap treated as agreement.",0,0],["independence","VARCHAR","text","independent, or same_upstream when both sources read the same data, or count the same thing by the same method, so agreement proves little.",0,0],["status","VARCHAR","text","agree, differs or not_available.",0,0],["explanation","VARCHAR","text","Why the gap exists, from registry/reconciliation_notes.csv.",["registry"],0],["gap_kind","VARCHAR","text","What sort of gap the note describes, from registry/reconciliation_notes.csv: open when no source says which figure is right, fault when one side is a known fault or a retired figure, defs when the two figures are right about different things, design when the method predicts a gap of this size. Empty for a check with no note, or with a note that is not about a gap.",["registry"],0]],"v":1},"dq_freshness":{"a":"Data quality","d":"How current each dataset is, relative to the newest snapshot the build can see, and whether that is too old. Covers the daily series and the datasets read as a snapshot each night. A dataset that falls further behind than its limit is stale, and the data test no_dataset_is_stale then fails, so a source that stops arriving is noticed.","g":["model"],"n":64,"f":null,"l":null,"s":["bigquery","bitwise","coinbase","coinmetrics","defillama","dune","explorer","fastnear","github","gov","hos","nearblocks","nearcatalog","neardata","revenue","rhea","rpc"],"c":[["dataset","VARCHAR","text","Readable dataset name.",0,0],["model","VARCHAR","text","Silver model name.",0,1],["cadence","VARCHAR","text","daily for a series with one value per day, snapshot for a dataset that holds only what was read each night.",0,0],["latest_snapshot","DATE","date","Newest snapshot holding this dataset.",0,1],["latest_data_day","DATE","date","Newest day of data. For a snapshot dataset, the day of its newest read.",0,1],["as_of","DATE","date","Newest snapshot across all datasets.",0,1],["days_behind","BIGINT","days","Days between latest_data_day and as_of. A daily series normally reads 1, because the newest full day is yesterday.",0,0],["max_days_behind","INTEGER","days","The most days this dataset may fall behind before it counts as stale: 3 for a daily series and 2 for a snapshot, which leaves room for one missed night, 7 for the Bitwise fund, which trades on weekdays and fills its chart a day late, and 35 for the Intents pool's chain readings, which are taken at month ends. Empty where no limit applies: a reading taken by hand, and NearBlocks' legacy charts, which are switched off on 2026-11-22.",["bitwise"],0],["is_stale","BOOLEAN","boolean","True when days_behind is over max_days_behind. Always false where there is no limit.",0,0],["rows_all_snapshots","BIGINT","count","Rows across all snapshots.",0,0]],"v":1},"dq_revisions":{"a":"Data quality","d":"Values a source changed after first publishing them, comparing the oldest and newest snapshot of the same key. This shows that a value moved, not when or how often; to date a change, compare consecutive snapshots in silver.","g":["model","value_column","series_key","date_day"],"n":9366,"f":"2021-05-21","l":"2026-11-12","s":["defillama","nearblocks","revenue"],"c":[["model","VARCHAR","text","Silver model name.",0,1],["value_column","VARCHAR","text","Column being compared.",0,1],["series_key","VARCHAR","text","Which series within the model.",0,1],["date_day","DATE","date","UTC calendar day.",0,1],["first_snapshot","DATE","date","Oldest snapshot holding this key.",0,1],["last_snapshot","DATE","date","Newest snapshot holding this key.",0,1],["first_value","DOUBLE","see value_column","Value in the oldest snapshot.",0,0],["last_value","DOUBLE","see value_column","Value in the newest snapshot.",0,0],["change_pct","DOUBLE","percent","Change from first to last, as a percentage.",0,0]],"v":1},"dq_ingest_runs":{"a":"Data quality","d":"How each dataset fared on each run date: ok, partial, skipped or failed, and why.","g":["snapshot_date","dataset"],"n":970,"f":"2026-11-01","l":"2026-11-14","s":[],"c":[["snapshot_date","DATE","date","Date of the run.",0,1],["dataset","VARCHAR","text","source/dataset.",0,1],["status","VARCHAR","text","ok, partial, skipped or failed.",0,0],["detail","VARCHAR","text","Why, when it was not ok.",0,0],["files","INTEGER","count","Files saved.",0,0],["seconds","DOUBLE","seconds","Time taken.",0,0]],"v":1},"dq_provenance":{"a":"Data quality","d":"Where the data came from, per dataset and snapshot. Cite this next to a chart so a reader can find the exact responses behind it.","g":["source","dataset","snapshot_date"],"n":1012,"f":"2026-10-28","l":"2026-11-14","s":[],"c":[["source","VARCHAR","id","Source name.",0,1],["dataset","VARCHAR","id","Dataset name.",0,1],["snapshot_date","DATE","date","Date the source was read.",0,1],["files","BIGINT","count","Bronze files.",0,0],["bytes","HUGEINT","bytes","Uncompressed size.",0,0],["declared_rows","HUGEINT","count","Rows, where the fetcher recorded them.",0,0],["example_url","VARCHAR","url","One URL read for this dataset.",0,0],["first_fetched_at","VARCHAR","timestamp","When the first file was fetched.",0,0],["last_fetched_at","VARCHAR","timestamp","When the last file was fetched.",0,0],["note","VARCHAR","text","Any change made before saving, such as trimming.",0,0]],"v":1},"dq_bigquery_tables":{"a":"Data quality","d":"Is NEAR's public BigQuery dataset still being loaded, and how large is it? One row per table on the newest read: rows, size, last change and the newest day that has rows. NEAR Lake, the feed the dataset's published loader reads, was switched off on 2026-03-24, and the loader's repository has not changed since 2025, so freshness is measured here, not assumed.","g":["table_name"],"n":16,"f":"2026-11-12","l":"2026-11-12","s":["bigquery"],"c":[["snapshot_date","DATE","date","Date the dataset was read.",0,1],["table_name","VARCHAR","text","Table or view in the dataset.",0,1],["table_type","VARCHAR","text","table or view.",0,0],["row_count","BIGINT","count","Rows in the table. A view has none of its own.",0,0],["size_gb","DOUBLE","GB","Size of the table's data.",0,0],["created_at","TIMESTAMP","UTC timestamp","When the table was created.",0,1],["last_modified_at","TIMESTAMP","UTC timestamp","When the table last changed: the last time its loader wrote to it.",0,1],["first_day_with_rows","DATE","date","Oldest daily partition that holds rows.",0,1],["newest_day_with_rows","DATE","date","Newest daily partition that holds rows.",0,1],["days_with_rows","BIGINT","days","Daily partitions that hold rows.",0,0],["days_behind_read","BIGINT","days","Days from newest_day_with_rows to the day of the read. 0 or 1 means the table was current.",0,0]]},"dq_bigquery_reads":{"a":"Data quality","d":"Every query this warehouse has run in BigQuery: which SQL file, over which days, how much data it read and what Google billed. The SQL is in ingest/sql/bigquery/, one file per query, and sql_sha256 is the hash of the text that ran, so a result can be tied to the exact query. Google bills by the gigabytes of the columns a query reads, and the first 1,000 GB of a month are free.","g":["snapshot_date","dataset","read_key"],"n":9,"f":"2026-11-12","l":"2026-11-12","s":["bigquery"],"c":[["snapshot_date","DATE","date","Snapshot the result was saved in.",0,1],["dataset","VARCHAR","text","Bronze dataset the result was saved as.",0,1],["query","VARCHAR","text","Name of the query: ingest/sql/bigquery/<query>.sql.",0,0],["read_key","VARCHAR","text","The days the read covered, as first day and last day, or the query's name where it has no window.",0,1],["sql_sha256","VARCHAR","hash","SHA-256 of the SQL text that ran.",0,0],["read_at","TIMESTAMP","UTC timestamp","When the query ran. Empty for a read saved before the loader recorded it.",0,1],["first_day","DATE","date","First day the query read, where it has a window.",0,1],["last_day","DATE","date","Last day the query read, where it has a window.",0,1],["gb_estimated","DOUBLE","GB","What BigQuery's free dry run said the query would read.",0,0],["gb_billed","DOUBLE","GB","What Google billed the query for. 0 when the result came from BigQuery's cache.",0,0],["is_cache_hit","BOOLEAN","boolean","True when BigQuery answered from its cache of an identical query run within the day before.",0,0],["rows_returned","BIGINT","count","Rows in the query's result.",0,0],["rows_saved","HUGEINT","count","Rows saved to bronze, over all pages. Equal to rows_returned for a complete read.",0,0],["pages","BIGINT","count","Pages the result arrived in.",0,0]]}},"fields":935};
